function combatants(){return [...enemies,...citizens,...officers,...remoteTargets()];}
function hurtTeam(t,d){if(t.kind==='decoy')return;if(t.kind==='remote')lanSend({type:'hurt',damage:d,zone,to:t.id});else hitPlayer(d);}
