function loop(now){requestAnimationFrame(loop);const elapsed=Math.max(0,(now-last)/1000||0);last=now;countPlay56(elapsed);if(!ready)return;const begin=performance.now();window.OmniSound?.ambient(started&&!paused&&!net.remoteAway&&!net.waiting&&!document.hidden,sound,zone,dayMode);netUpdate(Math.min(.1,elapsed));updateCinema(elapsed);if(started&&!paused&&!net.remoteAway&&!net.waiting){simulate75(elapsed);}else if(!started)clock+=Math.min(.04,elapsed);const render=frameControl75.render(now,quality17);if(render){draw();drawCinema();}sampleFrame201(now,render);frameControl75.sample(elapsed*1000,performance.now()-begin,started&&!paused&&!cinematic&&!document.hidden&&window.omniMode61!==null);}
function resize(){const scale=Math.min(innerWidth/W,innerHeight/H);$('#game').style.transform='translate(-50%,-50%) scale('+scale+')';}
function point(e){const r=$('#joystick').getBoundingClientRect(),scale=r.width/154;let x=(e.clientX-r.left)/scale-77,y=(e.clientY-r.top)/scale-77,len=Math.hypot(x,y);if(len>50){x*=50/len;y*=50/len;}stick.x=x/50;stick.y=y/50;$('#stick').style.transform='translate('+x+'px,'+y+'px)';}
$('#joystick').addEventListener('pointerdown',e=>{if(paused)return;e.preventDefault();stick.id=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);point(e);});$('#joystick').addEventListener('pointermove',e=>{if(e.pointerId===stick.id)point(e);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('#joystick').addEventListener(ev,e=>{if(e.pointerId===stick.id){stick.id=null;stick.x=stick.y=0;$('#stick').style.transform='';}});
document.querySelectorAll('[data-skill]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held=+b.dataset.skill;attack(held);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>held=-1);});
$('#ultrabasic').onclick=ultraBasic;$('#jobsbtn').onclick=jobsMenu;$('#alienskins').onclick=alienSkinMenu;$('#jump').onclick=jump;$('#lanbtn').onclick=lanMenu;$('#racebtn').onclick=raceMenu;$('#treebtn').onclick=skillTree;$('#moreattacks').onclick=()=>{attackPage=1-attackPage;held=-1;hud();};$('#musicbtn').onclick=settings15;$('#skins').onclick=skinMenu;$('#slide').onclick=slide;$('#transform').onclick=transform;$('#talk').onclick=interact;$('#dialprev').onclick=()=>selectAlien(-1);$('#dialnext').onclick=()=>selectAlien(1);$('#mapbtn').onclick=()=>showWorldMap();$('#pause').onclick=pauseMenu;$('#mission').onclick=()=>{if(hospital()){hauntDialog();return;}if(zone===23){story3Talk();return;}if(zone===12){if(dist(player,neko)<=145)nekoTalk();else toast('Acércate a Maid Neko');return;}if(zone===9){tenHub();return;}if(zone===11){storyTalk();return;}if(zone===10){if(dist(player,kim)<=145)danceMenu();else toast('Acércate a Kim Taehyung en el centro del concierto');return;}if(zone===6||zone===8){knightTalk();return;}if(npcHere()&&dist(player,npc)<=130)talk();else showDialog('DIARIO · SOMBRAS ENTRE LOS PINOS','Un camino seguro','<p>'+$('#questtext').textContent+'.</p><p>'+ (quest.state==='active'?'Encuentra a los seis drones y un comandante en la parte derecha del Refugio de Max. Los enemigos de otras zonas no cuentan para esta misión. Al derrotar a los siete, vuelve al guardabosques, en la izquierda.':quest.state==='done'?'Habla con Max para repetir la misión. Cada alien tiene maestría independiente.':'Max está en la zona Refugio, cerca del inicio. Usa el MAPA para orientarte. Acércate a él y pulsa HABLAR.')+'</p>',[['CONTINUAR',closeDialog]]);};
$('#play').onclick=()=>{if(!ready)return;started=true;paused=false;$('#menu').classList.add('hidden');$('#hud').classList.remove('hidden');cam.x=clamp(player.x-W*.48/sceneZoom(),0,cameraMaxX());cam.y=clamp(player.y-H*.64/sceneZoom(),0,cameraMaxY());tone(460,.12);hud();if(migrated)toast('Partida actualizada · Nivel y maestría conservados');else if(quest.state==='new')toast('Habla con Max · Usa el dial para elegir tu alien');save();};
document.addEventListener('keydown',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys[k]=true;if(e.repeat)return;if(k==='Escape'){dialogOpen?closeDialog():pauseMenu();}if(k==='t')transform();if(k==='j')jump();if(k==='f')slide();if(k==='k')skillTree();if(k==='v'){attackPage=1-attackPage;hud();}if(k==='e')interact();if(k==='q')selectAlien(-1);if(k==='r')selectAlien(1);if(k==='m')showWorldMap();if(k===' '){held=0;attack(0);}if('1234'.includes(k)&&k.length===1){held=+k-1;attack(held);}});document.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false;if('1234 '.includes(e.key))held=-1;});
document.addEventListener('visibilitychange',()=>{if(document.hidden){suspendCinema();save();resetInput();if(started&&!paused)pauseMenu();}});window.addEventListener('blur',resetInput);window.addEventListener('pagehide',save);window.addEventListener('resize',resize);window.pauseFromAndroid=()=>{if(cinematic){suspendCinema();save();return;}if(window.OmniCooking?.active){OmniCooking.pause();save();return;}if(window.OmniRhythm?.active){OmniRhythm.pause();save();return;}net.away=true;if(net.peer)netUpdate(.2);save();resetInput();if(started&&!paused)pauseMenu();};window.backFromAndroid=()=>{if(cinematic){suspendCinema();return;}if(window.OmniCooking?.active){OmniCooking.pause();return;}if(window.OmniRhythm?.active){OmniRhythm.pause();return;}if(dialogOpen)closeDialog();else pauseMenu();};
// v0.12: watch confirmation, protected transformation, recovery and Chapter 2.
let cinematic=null;
function initV12(){player.story2=Object.assign({state:'new',kills:[],reward:0},player.story2||{});player.story2.kills=[...new Set(player.story2.kills.filter(k=>['animo','frog','hog'].includes(k)))];player.watchOpen=false;player.watchTurn=0;}
function recoverWolf(){if(net.role==='guest'){lanSend({type:'wolfRecovery',zone});return;}const pool=zone===17?enemies:zoneStates.moonforest||[];const b=pool.find(e=>e.wolfBoss&&e.alive);if(b){b.recovering=true;b.wind=0;b.cast=0;}}
function updateRecovery(dt){if(net.role==='guest')return;const pool=zone===17?enemies:zoneStates.moonforest||[];for(const b of pool)if(b.wolfBoss&&b.alive&&b.recovering){b.hp=Math.min(b.max,b.hp+b.max*.02*dt);if(b.hp>=b.max)b.recovering=false;}}
function transform(){if(cinematic)return;if(interference()){toast('Interferencia magnética · sin formas');return;}if(race==='osmo'&&player.form==='ghost'){endGhost();revert(false);return;}if(race==='osmo'||player.alien){player.watchOpen=false;commitTransform();return;}if(!started||paused||player.jump>0||player.motion||player.leap)return;if(!player.watchOpen){player.watchOpen=true;player.watchTurn=.4;resetInput();toast('Elige con ◀ / ▶ y pulsa ACTIVAR');hud();return;}if(player.battery<=0){toast('Espera a recuperar algo de batería');return;}if(player.selected==='wolf'&&!wolfUnlocked()){toast('Blitztwolfer requiere nivel 30 y su ADN');return;}if(player.selected==='ghost'&&(!player.ghostDNA||player.level<20)){toast('Fantasmático requiere completar el hospital · nivel 20');return;}if(!cinemaEnabled){player.watchOpen=false;commitTransform();hud();return;}cinematic={mode:'press',time:0,id:player.selected,hold:false};paused=true;resetInput();window.OmniSound?.stopSample('dial');hud();if(net.peer)netUpdate(.2);}
function suspendCinema(){if(!cinematic)return;cinematic.hold=true;OmniSound.stopSample('heatblast',false);$('#cinemaresume').classList.remove('hidden');}
function resumeCinema(){if(!cinematic)return;cinematic.hold=false;net.away=false;$('#cinemaresume').classList.add('hidden');if(cinematic.mode==='movie')OmniSound.sample('heatblast',false);}
function updateCinema(dt){if(!cinematic||cinematic.hold||document.hidden)return;cinematic.time+=dt;if(cinematic.mode==='press'&&cinematic.time>=.7){if(['heatblast','grey','ultra'].includes(cinematic.id)||CINE13[cinematic.id]){cinematic.mode='movie';cinematic.time=0;document.body.classList.add('cinema');OmniSound.sample('heatblast');window.OmniMusic?.pauseForEvent();}else finishCinema();}else if(cinematic.mode==='movie'&&cinematic.time>=16.065306)finishCinema();}
function finishCinema(){if(!cinematic)return;const osmoCinema=!!cinematic.osmo;if(!osmoCinema)player.selected=cinematic.id;cinematic=null;player.watchOpen=false;document.body.classList.remove('cinema');$('#cinemaresume').classList.add('hidden');OmniSound.stopSample('heatblast');paused=false;net.away=false;if(!osmoCinema)commitTransform();resetInput();hud();if(net.peer)netUpdate(.2);}
function drawCinemaLegacy(){if(!cinematic||cinematic.mode!=='movie')return;const t=cinematic.time,map=CINE13[cinematic.id],ix=Math.min(5,Math.floor(Math.max(0,t-1)/2.45)),im=map?art[map[0]]:t<1?art.cineStart12:art.cine12,f=map?OMNI_V13_FRAMES[map[0]][map[1]+ix]:t<1?[0,0,im.width,im.height]:OMNI_V12_FRAMES.cine12[ix];ctx.save();ctx.fillStyle='#030508';ctx.fillRect(0,0,W,H);const scale=Math.min(W/f[2],H/f[3])*(1+.025*Math.sin(t*1.5)),w=f[2]*scale,h=f[3]*scale;ctx.drawImage(im,...f,(W-w)/2,(H-h)/2,w,h);for(let i=0;i<22;i++){ctx.fillStyle=(ALIENS[cinematic.id]?.color||'#c6ffa4')+'66';ctx.fillRect((i*127+t*110)%W,(i*71-t*45+H*4)%H,3+i%4,3+i%4);}ctx.fillStyle='#07140caa';ctx.fillRect(0,H-44,W,44);txt((ALIENS[cinematic.id]?.name||'TRANSFORMACIÓN').toUpperCase(),W/2,H-25,15,'#eaffcc');txt('DOBLE TOQUE PARA SALTAR',W/2,H-9,10,'#c9d6c2');ctx.fillStyle='#b7ff89';ctx.fillRect(0,H-3,W*t/16.065306,3);ctx.restore();}
function chaptersMenu(){showDialog('TEN · MODO HISTORIA','Capítulos de tu aventura','<p>Las misiones y recompensas se guardan por separado para cada raza.</p>',[['01 · ROBOT DE VILGAX',storyTalk],['02 · DR. ÁNIMO · NV.20',story2Talk],['03 · HEX · NV.30',story3Talk],['VOLVER',closeDialog]]);}
function canStartStory2(){return player.level>=20&&player.story.completions>=1&&player.story2.state==='new'&&zone===9&&dist(player,ten)<140;}
function startStory2(){if(!canStartStory2())return false;player.story2={state:'active',kills:[],reward:Math.round(xpNeed()*.9)};delete zoneStates.animoLab;closeDialog();toast('Capítulo 2 aceptado · Laboratorio al este de la Zona devastada');save();return true;}
function story2Kill(id){const q=player.story2;if(player.level<20||q.state!=='active'||!['animo','frog','hog'].includes(id)||q.kills.includes(id))return;q.kills.push(id);if(q.kills.length===3){q.state='return';toast('¡Laboratorio liberado! Regresa con Ten');}save();}
function claimStory2(){const q=player.story2;if(q.state!=='return'||zone!==9||dist(player,ten)>140)return false;const reward=q.reward;q.state='complete';q.reward=0;player.coins+=10;xp(reward);save();closeDialog();toast('Capítulo 2 completado · '+reward+' EXP · 10 monedas');return true;}
function story2Talk(){const q=player.story2,near=zone===9&&dist(player,ten)<140;let text=q.state==='complete'?'«Detuviste a Ánimo y a sus mutantes. A nivel 30 puedo contarte lo que ocurre con Hex en la Escuela Arcana.»':q.state==='return'?'«¡Buen trabajo! La ciudad vuelve a estar a salvo.»':q.state==='active'?'«Entra al laboratorio al este de la Zona devastada, al sur del Barrio. Detén a Ánimo y sus dos criaturas.»':'«Ánimo está creando mutantes. Necesito tu ayuda para detener su pistola de ácido, su rana y su bestia. ¿Aceptas?»';showDialog('TEN · HISTORIA 02 · NIVEL 20','El laboratorio de Dr. Ánimo','<p>'+text+'</p><p>Nivel mínimo 20 · Completa al menos una victoria del capítulo 1 · Una sola recompensa por raza.</p>'+(q.state==='active'?'<p>Derrotados: '+q.kills.length+' / 3. Sus ataques se anuncian antes de golpear.</p>':'')+(q.state==='complete'?'':'<p class="reward">'+(q.reward||Math.round(xpNeed()*.9))+' EXP + 10 monedas al volver con Ten.</p>'),[...(q.state==='new'&&canStartStory2()?[['ACEPTAR',startStory2]]:[]),...(q.state==='return'&&near?[['COBRAR',claimStory2]]:[]),['VOLVER',closeDialog]]);}
function ensureAnimo(){if(zone!==18||net.role==='guest'||enemies.some(e=>e.chapter2))return;for(const [i,id] of ['animo','frog','hog'].entries()){const hp=[1400,900,1100][i],x=[1200,890,650][i],y=[650,725,680][i];enemies.push({id:'c2-'+id,kind:'chapter2',chapter2:id,level:20,x,y,homeX:x,homeY:y,hp,max:hp,alive:true,face:-1,anim:0,moving:false,hit:0,stun:0,wind:0,frame:0,cd:2+i,altCD:5+i,growCD:12,growth:0,castData:null});}zoneStates.animoLab=enemies;}
function damageChapter2(e,damage){e.hp-=Math.round(damage);e.hit=.18;popup(e.x,e.y-135,String(Math.round(damage)));if(e.hp<=0){e.alive=false;e.hp=0;e.castData=null;story2Kill(e.chapter2);if(net.peer)lanSend({type:'story2Kill',id:e.chapter2,zone:18});burst(e.x,e.y-45,35,'#c4ef85');save();}}
function chapterCast(e,type,t,r,damage,cd){const target=teamTargets().sort((a,b)=>dist(a,e)-dist(b,e))[0]||player;e.castData={type,t,max:t,r,damage,a:Math.atan2(target.y-e.y,target.x-e.x),x:target.x,y:target.y,hit:false};if(type==='grow')e.growCD=cd;else if(['acidfan','leap','charge'].includes(type))e.altCD=cd;else e.cd=cd;}
function updateChapter2(dt){if(net.role==='guest')return;ensureAnimo();if(zone!==18)return;for(const e of enemies){if(!e.chapter2||!e.alive||e.possessedTime>0)continue;e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);e.cd=Math.max(0,e.cd-dt);e.altCD=Math.max(0,e.altCD-dt);e.growCD=Math.max(0,e.growCD-dt);e.growth=Math.max(0,e.growth-dt);e.moving=false;
 const f=e.castData;if(f){f.t-=dt;if(f.type==='leap'&&f.t<.6&&!f.hit)moveActor(e,(f.x-e.x)*Math.min(1,dt*8),(f.y-e.y)*Math.min(1,dt*8));if(f.type==='charge'&&f.t<.65&&f.t>.25)moveActor(e,Math.cos(f.a)*350*dt,Math.sin(f.a)*350*dt);if(!f.hit&&f.t<=.25){f.hit=true;if(f.type==='grow'){e.growth=8;burst(e.x,e.y-70,25,'#a1fa76');}else if(f.type.startsWith('acid')){for(const offset of f.type==='acidfan'?[-.18,0,.18]:[0])hostileShots.push({type:'green',x:e.x,y:e.y-35,dx:Math.cos(f.a+offset)*250,dy:Math.sin(f.a+offset)*250,t:2.7,r:9,damage:f.damage});}else for(const target of teamTargets()){const d=dist(e,target),a=Math.atan2(target.y-e.y,target.x-e.x),angle=Math.abs(Math.atan2(Math.sin(a-f.a),Math.cos(a-f.a)));if(d<f.r&&lineClear(e.x,e.y,target.x,target.y)&&(f.type==='leap'||angle<(f.type==='tongue'?.2:1)))hurtTeam(target,Math.round(f.damage*(e.growth>0?1.35:1)));if(paused||zone!==18)return;}OmniSound.play(f.type.startsWith('acid')?'spit':'hit');}if(f.t<=0)e.castData=null;continue;}if(e.stun>0)continue;const target=teamTargets().sort((a,b)=>dist(a,e)-dist(b,e))[0]||player,d=dist(e,target);e.face=target.x>=e.x?1:-1;if(d>850)continue;
 if(e.chapter2==='animo'){if(e.altCD<=0&&d<570)chapterCast(e,'acidfan',1.25,570,10,8);else if(e.cd<=0&&d<600)chapterCast(e,'acid',.95,600,14,4);}else if(e.chapter2==='frog'){if(e.altCD<=0&&d<450)chapterCast(e,'leap',1.5,105,18,7);else if(e.cd<=0&&d<300)chapterCast(e,'tongue',1.05,300,14,4);}else{if(e.growCD<=0)chapterCast(e,'grow',1.35,0,0,20);else if(e.altCD<=0&&d<370)chapterCast(e,'charge',1.4,115,18,7);else if(e.cd<=0&&d<115)chapterCast(e,'bite',.9,115,14,3);}
 if(!e.castData&&d>(e.chapter2==='animo'?250:90)){const speed=e.chapter2==='animo'?98:e.chapter2==='frog'?100:115;moveActor(e,(target.x-e.x)/d*speed*dt,(target.y-e.y)/d*speed*dt);e.anim+=dt*6;e.moving=true;}}
}
function drawChapter2(e){const f=e.castData,id=e.chapter2,h=id==='animo'?135:id==='frog'?105:e.growth>0?158:118;let frame=e.moving?1+Math.floor(e.anim)%2:0,lift=0;if(f){if(id==='animo')frame=f.type==='acidfan'?5:f.hit?4:3;else if(id==='frog'){frame=f.type==='tongue'?(f.hit?7:6):f.t>.6?3:f.hit?5:4;if(f.type==='leap'&&f.t<=.6&&!f.hit)lift=Math.sin((.6-f.t)/.6*Math.PI)*100;}else frame=f.type==='grow'?5:f.type==='charge'?4:3;}else if(e.hit>0&&id==='animo')frame=6;else if(e.growth>0&&!e.moving)frame=6;sprite({animo:50,frog:51,hog:52}[id],frame,e.x,e.y-lift,h,e.face,e.hit>0?.65:1);txt(({animo:'DR. ÁNIMO',frog:'RANA MUTANTE',hog:'BESTIA MUTANTE'})[id]+' · NV.20',e.x,e.y-h-18,9,'#dcf7b1');ctx.fillStyle='#172419';ctx.fillRect(e.x-55,e.y-h-10,110,5);ctx.fillStyle='#b6e57e';ctx.fillRect(e.x-55,e.y-h-10,110*Math.max(0,e.hp/e.max),5);
 if(f){ctx.save();ctx.strokeStyle=f.hit?'#d6ff8a':'#ffa277';ctx.fillStyle='#b4f25725';ctx.lineWidth=f.hit?5:2;ctx.beginPath();if(f.type==='leap'){ctx.ellipse(f.x,f.y,105,37,0,0,Math.PI*2);}else if(f.type==='grow'){ctx.ellipse(e.x,e.y,75,25,0,0,Math.PI*2);}else{ctx.moveTo(e.x,e.y);ctx.arc(e.x,e.y,f.r,f.a-(f.type==='tongue'?.12:.23),f.a+(f.type==='tongue'?.12:.23));ctx.closePath();}ctx.fill();ctx.stroke();if(f.type==='tongue'&&f.hit){ctx.strokeStyle='#ef8496';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(e.x,e.y-35);ctx.lineTo(e.x+Math.cos(f.a)*f.r,e.y+Math.sin(f.a)*f.r-25);ctx.stroke();}ctx.restore();}}
function hudV12(){if(race==='omni'&&!player.alien){text193($('#transformlabel'),player.watchOpen?'ACTIVAR':'ABRIR RELOJ');text193($('#transformhint'),player.watchOpen?alien().name.toUpperCase():'ELIGE TU ALIEN');}if(zone===18){text193($('#mission .tiny'),'HISTORIA 02 · DR. ÁNIMO');text193($('#questtext'),player.story2.state==='active'?'Detén a los mutantes · '+player.story2.kills.length+' / 3':player.story2.state==='return'?'Regresa con Ten':player.story2.state==='complete'?'Capítulo 2 completado':'Ten · Requiere nivel 20');text193($('#questsub'),'Laboratorio · Salida al oeste');}if(zone===17&&enemies.some(e=>e.wolfBoss&&e.alive&&e.recovering))$('#wolfbar').textContent+=' · RECUPERANDO';}

// OMNI 0.13 - spectral expedition, per-race portals and cinematic controls.
let cinemaEnabled=localStorage.getItem('omni-cinematics')!=='0',lastCinemaTap=0,cinemaTapPos=null;
const CINE13={diamond:['cineA13',0],fourarms:['cineA13',6],xlr8:['cineB13',0],bestia:['cineB13',6],insect:['cineC13',0],aquatic:['cineC13',6],wolf:['cineD13',0],ghost:['cineD13',6]};
const GHOST_SKILLS=[makeSkill('Intangibilidad','FASE',0,12,0),makeSkill('Invisibilidad','INVISIBLE',0,15,15),makeSkill('Posesión','POSEER',14,14,40),makeSkill('Tentáculos retráctiles','TENTÁCULOS',24,.85,0),{...makeSkill('Pulso espectral','PULSO',52,9),points:3},{...makeSkill('Lamento del vacío','LAMENTO',20,12),points:3}];
ALIENS.ghost={name:'Fantasmático',hp:350,row:70,color:'#d7afff',skills:GHOST_SKILLS};CORE_ALIENS.push('ghost');SPEEDS.ghost=220;OSMO_FORMS.ghost={name:'Osmosiano espectral',hp:350,color:'#c9a7f2'};OSMO_SKILLS.ghost=GHOST_SKILLS;
const SWITCHES=[{x:385,y:555},{x:850,y:810},{x:1385,y:565}],LAMPS=[{x:310,y:660},{x:1280,y:660}];
const ECTO=[{x:470,y:560,w:240,h:175},{x:1015,y:650,w:220,h:180}];
const FRAGILE=[{x:710,y:600,w:90,h:100},{x:800,y:600,w:90,h:100},{x:890,y:600,w:90,h:100}];
let hauntWorld={switches:[false,false,false],tiles:[0,0,0],lamps:[0,0]},hauntClock=0;
const ghostForm=(o=player)=>o===player?race==='osmo'?o.form==='ghost':o.alien&&o.activeAlien==='ghost':o.race==='osmo'?o.form==='ghost':o.alien&&o.activeAlien==='ghost';
const fireForm=o=>o===player?race==='osmo'?o.form==='fire':o.alien&&o.activeAlien==='heatblast':o.race==='osmo'?o.form==='fire':o.alien&&o.activeAlien==='heatblast';
const hospital=()=>zone>=19&&zone<=22;
const interference=()=>zone===20;
const inRect=(o,r)=>o.x>=r.x&&o.x<=r.x+r.w&&o.y>=r.y&&o.y<=r.y+r.h;
function initV13(){player.warps=Array.isArray(player.warps)?[...new Set(player.warps.filter(n=>Number.isInteger(n)&&n>=0&&n<REGIONS.length&&![20,21,22].includes(n)))]:[];player.haunt=Object.assign({phase:0,switches:[false,false,false],complete:false},player.haunt||{});player.haunt.switches=[0,1,2].map(i=>!!player.haunt.switches[i]);player.ghostDNA=!!player.ghostDNA;player.ghostCorrupt=clamp(Number(player.ghostCorrupt)||0,0,100);player.ghostLock=Math.max(0,Number(player.ghostLock)||0);player.ghostPhase=player.ghostInvisible=player.ghostPulse=player.detection=0;player.possession=null;player.crouching=false;player.safeGhost={x:player.x,y:player.y};player.hauntHazard=0;hauntWorld={switches:[...player.haunt.switches],tiles:[0,0,0],lamps:[0,0]};if(interference()){player.alien=false;player.form='human';player.battery=0;}}
function toggleCinema(){cinemaEnabled=!cinemaEnabled;localStorage.setItem('omni-cinematics',cinemaEnabled?'1':'0');OmniSound.stopSample('dial');OmniSound.stopSample('heatblast');toast(cinemaEnabled?'Animaciones y sonidos de transformación activados':'Transformación directa · animaciones y sonidos desactivados');hud();}
function skipCinema(){if(cinematic?.mode!=='movie')return false;finishCinema();return true;}
function cinemaDoubleTap(e){if(!cinematic||cinematic.mode!=='movie'||e.target!==canvas&&e.target!==$('#cinemaworld'))return;const now=performance.now(),p={x:e.clientX,y:e.clientY};if(lastCinemaTap&&now-lastCinemaTap<340&&cinemaTapPos&&dist(p,cinemaTapPos)<85){lastCinemaTap=0;skipCinema();return;}lastCinemaTap=now;cinemaTapPos=p;}
function toggleWatchOff(){player.watchOpen=false;player.watchTurn=0;OmniSound.stopSample('dial');hud();}
function ghostPose(o){if(hasGhostLady(o))return {row:74,f:underwater()?(o.moving?10+walkFrame166(o,2,Math.floor(o.anim)%2):10):o.possession?6:o.attack>0?o.ghostFrame||3:o.ghostPhase>0?4:o.ghostInvisible>0?5:o.moving?1+walkFrame166(o,2,Math.floor(o.anim)%2):0,lift:8+Math.sin(clock*3)*4};return {row:o.race==='osmo'||o===player&&race==='osmo'?71:70,f:o.possession?6:o.attack>0?o.ghostFrame||3:o.ghostPhase>0?4:o.ghostInvisible>0?5:o.moving?1+walkFrame166(o,2,Math.floor(o.anim)%2):0,lift:8+Math.sin(clock*3)*4};}
function endGhost(){if(player.possession)endPossession();if(isSolid(player.x,player.y)){player.x=player.safeGhost?.x||region().minX+65;player.y=player.safeGhost?.y||region().exitY;}player.ghostPhase=player.ghostInvisible=player.ghostPulse=0;}
function ghostAttack(i){const s=GHOST_SKILLS[i];if(!unlockedSkill('ghost',i)){toast(i>=4?'Aprende esta habilidad por 3 puntos':'Requiere maestría '+s.unlock);return;}player.cool[i]=s.cd;player.attack=.65;player.ghostFrame=hasGhostLady()?[4,5,6,7,8,9][i]:[4,5,6,7,4,7][i];const d=s.damage*multiplier(),t=nearest(i===2?260:330);if(i===0){player.ghostPhase=3;player.safeGhost={x:player.x,y:player.y};}else if(i===1)player.ghostInvisible=5;else if(i===2){if(!t){player.cool[i]=1;toast('Acércate a un enemigo');return;}if(t.guard||t.hexBoss&&t.shield>0||t.ghostBoss&&t.immune){player.cool[i]=1;toast(t.guard?'Interferencia: el guardia no puede ser poseído':t.hexBoss?'Espera a que caiga el escudo':'Primero ilumina al espectro');return;}if(t.possessedBy){player.cool[i]=1;toast('Este enemigo ya está poseído');return;}player.possession={id:t.id,t:(t.hexBoss||t.majorBoss||t.wolfBoss||t.robotBoss||t.chapter2||t.ghostBoss)?2:4,tick:0,damage:d,origin:{x:player.x,y:player.y}};player.x=t.x;player.y=t.y;t.possessedBy=net.role==='guest'?'guest':'host';t.possessedTime=player.possession.t+.3;if(net.role==='guest')lanSend({type:'possess',id:t.id,zone,seq:++net.seq});}else if(i===3){player.ghostInvisible=0;const a=t?Math.atan2(t.y-player.y,t.x-player.x):Math.atan2(player.dy,player.dx);effects.push({type:'ghostlash',x:player.x,y:player.y,a,r:190,t:.5,max:.5});for(const e of combatants())if(e.alive&&dist(e,player)<190&&lineClear(player.x,player.y,e.x,e.y))damageTarget(e,d,.1);}else if(i===4){areaHit(player.x,player.y,180,d,.4);effects.push({type:'ghostpulse',x:player.x,y:player.y,r:180,t:.7,max:.7});}else{player.ghostPulse=1.5;player.ghostPulseTick=0;}}
function endPossession(){const p=player.possession;if(!p)return;const e=enemies.find(e=>e.id===p.id);if(e&&net.role!=='guest'){e.possessedTime=0;e.possessedBy=null;}player.x=p.origin.x;player.y=p.origin.y;player.possession=null;if(net.role==='guest')lanSend({type:'releasePossession',id:p.id,zone});}
function absorbGhost(){if(race!=='osmo'||!player.ghostDNA||player.level<20){toast('Completa la misión del hospital (nivel 20) para obtener ADN');return false;}if(interference()||player.battery<=0||player.ghostLock>0){toast(player.ghostLock>0?'ADN inestable · '+Math.ceil(player.ghostLock)+' s':'La interferencia impide absorber');return false;}if(player.form==='ghost'){closeDialog();return true;}const ratio=player.hp/maxHP();endGhost();player.form='ghost';refreshOsmo();player.hp=clamp(ratio*maxHP(),1,maxHP());player.cool=player.cooldowns.ghost;closeDialog();if(cinemaEnabled){cinematic={mode:'movie',id:'ghost',time:0,hold:false,osmo:true};paused=true;document.body.classList.add('cinema');OmniSound.sample('heatblast');resetInput();}save();return true;}
function updateGhost13(dt){player.ghostLock=Math.max(0,player.ghostLock-dt);player.ghostInvisible=Math.max(0,player.ghostInvisible-dt);const phase=player.ghostPhase;player.ghostPhase=Math.max(0,phase-dt);if(phase>0&&!player.ghostPhase&&isSolid(player.x,player.y)){player.x=player.safeGhost.x;player.y=player.safeGhost.y;}if(!isSolid(player.x,player.y))player.safeGhost={x:player.x,y:player.y};if(!ghostForm()){if(player.possession)endPossession();player.ghostPhase=player.ghostInvisible=0;player.ghostCorrupt=Math.max(0,player.ghostCorrupt-dt*3);}else if(race==='osmo'){const old=player.ghostCorrupt;player.ghostCorrupt=Math.min(100,old+dt*2);if(old<70&&player.ghostCorrupt>=70)toast('¡ALERTA! Este poder te controla. Vuelve a tu forma base.');if(player.ghostCorrupt>=70){player.regenWait=12;player.hp=Math.max(1,player.hp-maxHP()*.012*dt);}if(player.ghostCorrupt>=100){player.ghostLock=150;endGhost();revert(false);toast('CORRUPCIÓN TOTAL · ADN bloqueado 150 segundos');save();}}
 const p=player.possession;if(p){p.t-=dt;const e=enemies.find(e=>e.id===p.id);if(!e?.alive||p.t<=0){endPossession();}else{e.x=player.x;e.y=player.y;e.moving=player.moving;e.anim=player.anim;p.tick-=dt;if(p.tick<=0){p.tick+=1;damageTarget(e,p.damage,.3);for(const o of enemies)if(o!==e&&o.alive&&dist(o,e)<130)damageTarget(o,p.damage,.3);}}}if(net.role!=='guest')for(const e of enemies)if(e.possessedTime>0){e.possessedTime=Math.max(0,e.possessedTime-dt);const owner=net.members[e.possessedPeer];if(e.possessedBy==='guest'&&owner?.possession?.id===e.id){moveActor(e,owner.x-e.x,owner.y-e.y);e.moving=owner.moving;e.anim=owner.anim;}if(!e.possessedTime)e.possessedBy=null;}
 if(player.ghostPulse>0){player.ghostPulse-=dt;player.ghostPulseTick-=dt;if(player.ghostPulseTick<=0){player.ghostPulseTick+=.5;areaHit(player.x,player.y,205,20*multiplier(),.15);effects.push({type:'ghostpulse',x:player.x,y:player.y,r:205,t:.5,max:.5});}}
}
function warpAllowedDestination(n){if(inVoid()||n>=24)return false;return Number.isInteger(n)&&n>=0&&n<REGIONS.length&&![20,21,22].includes(n);}
function buyWarp(n){if(!warpAllowedDestination(n)||player.warps.includes(n)||player.coins<50||!discovered.includes(REGIONS[n].id))return false;player.coins-=50;player.warps.push(n);save();return true;}
function travelWarp(n){if(!player.warps.includes(n)||!warpAllowedDestination(n))return false;if(cinematic||player.regenWait>0||law.timer>0||[20,21,22].includes(zone)||player.possession){toast('Sal del combate o de la misión del hospital antes de viajar');return false;}if(net.role==='guest'){lanSend({type:'warpRequest',zone,n});closeDialog();toast('Teletransporte solicitado al anfitrión');return true;}if(net.peer&&(Object.values(net.members).some(o=>o.regenWait>0)||net.remoteAway)){toast('Tu compañero debe salir del combate y cerrar sus menús');return false;}closeDialog();enterZone(n,'center');player.inv=2;if(net.peer)netUpdate(.2);return true;}
function warpMenu(n){if([20,21,22].includes(n)){showDialog('HOSPITAL · SIN PORTALES','Solo entrada exterior','<p>No se compran portales al interior. Viaja al exterior y entra caminando para realizar las fases de la misión.</p>',[['ENTRADA DEL HOSPITAL',()=>showWorldMap(19)],['VOLVER',closeDialog]]);return;}showDialog('PORTAL · '+REGIONS[n].name,'Teletransporte del mapa','<p>Desbloquear este destino cuesta <b>50 monedas una sola vez por raza</b>. Después, viajar es gratis. Debes haber visitado la zona. En Wi-Fi, viaja todo el grupo; puede solicitarlo cualquiera con el destino comprado.</p><p>No permite saltarse las fases del hospital ni escapar durante un combate.</p><p>Monedas: '+player.coins+' · '+(player.warps.includes(n)?'PORTAL DESBLOQUEADO':discovered.includes(REGIONS[n].id)?'ZONA VISITADA':'PRIMERO EXPLORA ESTA ZONA')+'</p>',[...(warpAllowedDestination(n)?player.warps.includes(n)?[['VIAJAR',()=>travelWarp(n)]]:discovered.includes(REGIONS[n].id)?[['DESBLOQUEAR · 50',()=>{if(buyWarp(n))warpMenu(n);else toast('Necesitas 50 monedas');}]]:[]:[]),['VOLVER AL MAPA',()=>showWorldMap(n)]]);}
function hauntDialog(){const q=player.haunt;showDialog('EXPEDICIÓN ESPECTRAL · NIVEL 20','El hospital abandonado','<p>Una interferencia magnética oculta un laboratorio bajo el hospital.</p><p><b>1. Sigilo:</b> sin transformaciones ni batería. Escóndete detrás de cajas/pilares y espera a que pasen los guardias. Si te detectan, vuelves al inicio del pasillo.</p><p><b>2. Sabotaje:</b> activa tres interruptores. El ectoplasma daña y las baldosas agrietadas ceden. XLR8 o Insecotide ayudan; también existe un recorrido a pie.</p><p><b>3. Contención:</b> ilumina a Fantasmático con fuego o las lámparas para volverlo sólido. Sus ataques de 30–40 se pueden esquivar.</p><p>'+ (q.complete?(player.ghostDNA?'ADN desbloqueado con esta raza.':'Misión completada. Repite el jefe y escanea su ADN (20 %).'):q.phase?'Fase actual: '+q.phase:'Recompensa: ADN espectral: Omnitrix requiere escanear (20 %); Osmosiano conserva la recompensa de absorción.')+'</p>',[...(zone===19&&!q.phase&&player.level>=20?[['INICIAR MISIÓN',()=>{player.haunt.phase=1;save();closeDialog();toast('Entra por el norte · nivel 20');}]]:[]),['CONTINUAR',closeDialog]]);}
function hospitalGate(next){if(net.applying)return true;if(next>=20&&next<=22){if(player.level<20||player.haunt.phase<1){toast('Acepta la expedición en el exterior del hospital · Nivel 20');return false;}if(next===22&&player.haunt.phase<3){toast('Primero apaga los tres interruptores del laboratorio');return false;}if(next===21&&zone===20){player.haunt.phase=Math.max(2,player.haunt.phase);player.crouching=false;save();}}return true;}
function enteredHospital(previous){player.watchOpen=false;player.detection=0;player.hauntHazard=0;if(zone===20){if(previous!==20)player.storedBattery=player.battery;endGhost();if(player.alien||race==='osmo'&&player.form!=='human')revert(false);player.battery=0;player.crouching=false;}else if(previous===20){player.battery=Math.max(35,Math.min(100,player.storedBattery||0));if(zone===21&&player.level>=20&&player.haunt.phase>0)player.haunt.phase=Math.max(2,player.haunt.phase);}if(zone===21&&net.role!=='guest'){hauntWorld.switches=[...player.haunt.switches];hauntWorld.tiles=[0,0,0];}if(zone===22&&player.haunt.phase>=3)ensureGhostBoss();if(hospital())hud();}
function hospitalCheckpoint(reason){endGhost();player.detection=0;player.crouching=false;player.hp=maxHP();player.regenWait=12;player.inv=2;player.x=zone===22?180:125;player.y=zone===20?815:790;player.leap=player.motion=null;player.jump=0;projectiles.length=hostileShots.length=effects.length=0;resetInput();if(zone===22&&net.role!=='guest'){const b=enemies.find(e=>e.ghostBoss&&e.alive);if(b){b.hp=b.max;b.castData=null;b.cd=3;b.altCD=6;b.blastCD=9;}}toast(reason+' · Reintenta desde este punto');save();}
function seedGuards(){if(zone!==20||net.role==='guest')return;enemies=[0,1,2].map((i)=>({id:'guard'+i,kind:'guard',guard:true,x:[540,950,1330][i],y:[585,750,610][i],homeX:[540,950,1330][i],homeY:[585,750,610][i],hp:9999,max:9999,alive:true,face:i%2?1:-1,anim:0,moving:true,hit:0,stun:0,patrol:0}));zoneStates[region().id]=enemies;}
function guardSees(e,o){const d=dist(e,o);if(d<45)return true;const a=Math.atan2(o.y-e.y,o.x-e.x),f=e.face>0?0:Math.PI;return d<(o.crouching?170:260)&&Math.abs(Math.atan2(Math.sin(a-f),Math.cos(a-f)))<.48&&lineClear(e.x,e.y,o.x,o.y);}
function triggerSwitch(i){if(zone!==21||player.haunt.phase<2||dist(player,SWITCHES[i]||{x:-999,y:-999})>95)return false;if(net.role==='guest'){lanSend({type:'hauntSwitch',i,zone});return true;}hauntWorld.switches[i]=true;syncHauntProgress();if(net.peer)netUpdate(.2);return true;}
function syncHauntProgress(){if(player.level<20||player.haunt.phase<1)return;player.haunt.switches=[...hauntWorld.switches];if(hauntWorld.switches.every(Boolean)){player.haunt.phase=Math.max(3,player.haunt.phase);toast('Máquinas apagadas · La sombra espera al este');}save();}
function hauntAction(){if(zone===19){hauntDialog();return;}if(zone===20){player.crouching=!player.crouching;hud();return;}if(zone===21){let i=SWITCHES.findIndex(s=>dist(player,s)<95);if(i>=0)triggerSwitch(i);else toast('Acércate a un interruptor');return;}if(zone===22){let i=LAMPS.findIndex(s=>dist(player,s)<120);if(i>=0){if(net.role==='guest')lanSend({type:'hauntLamp',i,zone});else hauntWorld.lamps[i]=12;toast('Lámpara encendida · 12 s');}else toast('Acércate a una lámpara para iluminar al espectro');}}
function ensureGhostBoss(){if(zone!==22||net.role==='guest'||enemies.some(e=>e.ghostBoss))return;enemies.push({id:'ghost-boss',kind:'ghostboss',ghostBoss:true,level:20,x:1080,y:690,homeX:1080,homeY:690,hp:2600,max:2600,alive:true,face:-1,anim:0,moving:false,hit:0,stun:0,immune:false,cycle:0,lit:0,cd:3,altCD:6,blastCD:9,castData:null});zoneStates[region().id]=enemies;}
function ghostVictory(){if(player.haunt.phase<3||player.haunt.complete||player.level<20)return;player.haunt.complete=true;player.ghostDNA=true;xp(650);player.coins+=10;save();toast(race==='omni'?'¡ADN DE FANTASMÁTICO! Selecciónalo en tu reloj':'¡ADN ESPECTRAL! Nueva absorción · cuidado con la corrupción');}
function ghostBossDamage(e,d){const fire=net.source==='guest'?fireForm(net.remote):fireForm(player);if(e.immune&&!fire){popup(e.x,e.y-150,'INTANGIBLE','#cca4ff');return;}if(fire){e.lit=4;e.immune=false;}e.hp-=Math.round(d);e.hit=.17;popup(e.x,e.y-160,String(Math.round(d)));if(e.hp<=0&&e.alive){e.hp=0;e.alive=false;e.respawn=60;e.castData=null;const owner=net.source;net.source=null;ghostVictory();net.source=owner;if(net.peer)lanSend({type:'ghostVictory',zone});rollGhostSkin();burst(e.x,e.y-75,45,'#dfb9ff');save();}}
function ghostBossCast(b,type,t,r,damage,cd){const target=teamTargets().sort((a,c)=>dist(a,b)-dist(c,b))[0];b.castData={type,t,max:t,r,damage,a:Math.atan2(target.y-b.y,target.x-b.x),x:target.x,y:target.y,hit:false};b[type==='lash'?'cd':type==='orb'?'altCD':'blastCD']=cd;}
function updateGhostBoss(dt){if(net.role==='guest'||zone!==22)return;ensureGhostBoss();const dead=enemies.find(e=>e.ghostBoss&&!e.alive);if(dead){dead.respawn=Math.max(0,(dead.respawn??60)-dt);if(dead.respawn===0){enemies.splice(enemies.indexOf(dead),1);ensureGhostBoss();}}const b=enemies.find(e=>e.ghostBoss&&e.alive);if(!b||b.possessedTime>0)return;for(const k of ['cd','altCD','blastCD','hit','stun','lit'])b[k]=Math.max(0,(b[k]||0)-dt);b.cycle+=dt;const lit=[player,...remoteTargets()].some(o=>fireForm(o)&&dist(o,b)<320)||LAMPS.some((l,i)=>hauntWorld.lamps[i]>0&&dist(l,b)<650);if(lit)b.lit=1;b.immune=b.cycle%10>6&&b.lit<=0;b.moving=false;const f=b.castData;if(f){f.t-=dt;if(!f.hit&&f.t<=.25){f.hit=true;if(f.type==='orb')hostileShots.push({type:'ghostorb',x:b.x,y:b.y-35,dx:Math.cos(f.a)*230,dy:Math.sin(f.a)*230,r:12,t:3,damage:35});else for(const t of teamTargets()){const a=Math.atan2(t.y-b.y,t.x-b.x),angle=Math.abs(Math.atan2(Math.sin(a-f.a),Math.cos(a-f.a)));if(dist(t,b)<f.r&&(f.type==='burst'||angle<.7)&&lineClear(b.x,b.y,t.x,t.y))hurtTeam(t,f.damage);}if(zone!==22)return;OmniSound.play('crystal');}if(f.t<=0)b.castData=null;return;}if(b.stun>0)return;const target=teamTargets().sort((a,c)=>dist(a,b)-dist(c,b))[0],d=dist(target,b);b.face=target.x>b.x?1:-1;if(d>800)return;if(d<190&&b.cd<=0)ghostBossCast(b,'lash',1,210,30,4);else if(d<260&&b.blastCD<=0)ghostBossCast(b,'burst',1.4,260,40,9);else if(d<600&&b.altCD<=0)ghostBossCast(b,'orb',1.1,600,35,6);else if(d>140){moveActor(b,(target.x-b.x)/d*135*dt,(target.y-b.y)/d*135*dt);b.moving=true;b.anim+=dt*6;}}
function updateHospital(dt){if(!hospital())return;hauntClock+=dt;if(zone===20){player.battery=0;player.alien=false;if(race==='osmo'&&player.form!=='human'){player.form='human';refreshOsmo();player.hp=Math.min(player.hp,maxHP());}if(net.role!=='guest')for(const e of enemies){e.patrol+=dt;e.face=Math.sin(e.patrol*.42+Number(e.id.slice(-1))*2)>0?1:-1;moveActor(e,e.face*48*dt,0);e.x=clamp(e.x,e.homeX-165,e.homeX+165);e.anim+=dt*5;}const spotted=enemies.some(e=>e.guard&&guardSees(e,player));player.detection=clamp(player.detection+dt*(spotted?player.crouching?.9:1.5:-1.7),0,1);if(player.detection>=1){hospitalCheckpoint('Guardia: eliminado');return;}}if(zone===21){const flying=player.alien&&player.activeAlien==='insect'&&player.flight>0||player.jump>0||player.ghostPhase>0;player.hauntHazard=Math.max(0,player.hauntHazard-dt);if(!flying&&ECTO.some(r=>inRect(player,r))&&player.hauntHazard<=0){player.hauntHazard=1;hitPlayer(8);}if(net.role!=='guest'){for(let i=0;i<3;i++){if(hauntWorld.tiles[i]>0){hauntWorld.tiles[i]+=dt;if(hauntWorld.tiles[i]>7)hauntWorld.tiles[i]=0;}else if([player,...remoteTargets()].some(o=>inRect(o,FRAGILE[i])&&!(o.alien&&o.activeAlien==='insect'&&o.flight>0)&&!(o.jump>0)))hauntWorld.tiles[i]=.001;}}if(!flying&&FRAGILE.some((r,i)=>hauntWorld.tiles[i]>1.1&&hauntWorld.tiles[i]<6&&inRect(player,r))){player.x=130;player.y=800;player.hp=Math.max(1,player.hp-maxHP()*.15);player.regenWait=12;toast('El suelo cedió · vuelve a intentarlo');}if(player.haunt.phase>=2&&hauntWorld.switches.some((v,i)=>v!==player.haunt.switches[i]))syncHauntProgress();}if(net.role!=='guest')hauntWorld.lamps=hauntWorld.lamps.map(v=>Math.max(0,v-dt));updateGhostBoss(dt);}
function drawGuard(e){sprite(73,player.detection>.4?5:1+Math.floor(e.anim)%2,e.x,e.y,110,e.face);ctx.save();ctx.fillStyle=player.detection>.5?'#ff535344':'#ffeb9225';ctx.strokeStyle='#f6e29b55';ctx.beginPath();ctx.moveTo(e.x,e.y);const a=e.face>0?0:Math.PI;ctx.arc(e.x,e.y,260,a-.48,a+.48);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
function drawGhostBoss(b){const f=b.castData,frame=b.immune?5:b.lit>0&&b.hit>0?6:f?f.type==='lash'?(f.hit?4:3):7:b.moving?1+Math.floor(b.anim)%2:0;sprite(72,frame,b.x,b.y+Math.sin(clock*3)*5,175,b.face,b.immune?.45:1);txt('FANTASMÁTICO · NV.20',b.x,b.y-197,11,'#ead0ff');txt(b.immune?'INTANGIBLE · ILUMÍNALO':'SÓLIDO',b.x,b.y-213,9,b.immune?'#c89aff':'#ffe698');ctx.fillStyle='#25172f';ctx.fillRect(b.x-75,b.y-190,150,7);ctx.fillStyle='#c9a4ed';ctx.fillRect(b.x-75,b.y-190,150*b.hp/b.max,7);if(f){ctx.fillStyle=f.hit?'#d49aff77':'#be79ee22';ctx.strokeStyle='#e9b9ff';ctx.lineWidth=f.hit?6:2;ctx.beginPath();if(f.type==='burst')ctx.ellipse(b.x,b.y,f.r,f.r*.5,0,0,Math.PI*2);else{ctx.moveTo(b.x,b.y);ctx.arc(b.x,b.y,f.r,f.a-.35,f.a+.35);ctx.closePath();}ctx.fill();ctx.stroke();}}
function drawHospitalFloor(){if(zone===20){for(const b of region().colliders.filter(b=>b.y>500)){ctx.fillStyle='#242132';ctx.fillRect(b.x,b.y-38,b.w,b.h+38);ctx.strokeStyle='#a19799';ctx.strokeRect(b.x,b.y-38,b.w,b.h+38);ctx.beginPath();ctx.moveTo(b.x,b.y-38);ctx.lineTo(b.x+b.w,b.y+b.h);ctx.moveTo(b.x+b.w,b.y-38);ctx.lineTo(b.x,b.y+b.h);ctx.stroke();}txt('SALIDA AL LABORATORIO →',1370,535,12,'#9df4bd');}if(zone===21){for(const r of ECTO){ctx.fillStyle='#753ba4bb';ctx.fillRect(r.x,r.y,r.w,r.h);for(let i=0;i<15;i++){ctx.fillStyle='#ce7cde88';ctx.fillRect(r.x+(i*51)%r.w,r.y+(i*23)%r.h+Math.sin(clock*3+i)*5,14,6);}}FRAGILE.forEach((r,i)=>{ctx.fillStyle=hauntWorld.tiles[i]>1.1&&hauntWorld.tiles[i]<6?'#090713':hauntWorld.tiles[i]>0?'#af6574':'#676475';ctx.fillRect(r.x+2,r.y+2,r.w-4,r.h-4);ctx.strokeStyle='#211c30';ctx.beginPath();ctx.moveTo(r.x+10,r.y+8);ctx.lineTo(r.x+50,r.y+55);ctx.lineTo(r.x+22,r.y+90);ctx.stroke();});SWITCHES.forEach((o,i)=>{ctx.fillStyle='#252f3e';ctx.fillRect(o.x-23,o.y-35,46,35);ctx.fillStyle=hauntWorld.switches[i]?'#99ef95':'#ef8c9c';ctx.fillRect(o.x-12,o.y-27,24,16);txt('INTERRUPTOR '+(i+1),o.x,o.y-46,10,'#dbdaf5');});}if(zone===22)LAMPS.forEach((o,i)=>{ctx.fillStyle=hauntWorld.lamps[i]>0?'#fff1ad':'#777188';ctx.fillRect(o.x-10,o.y-70,20,33);ctx.fillStyle='#59586a';ctx.fillRect(o.x-4,o.y-37,8,37);txt('LUZ · E',o.x,o.y-85,10,'#ecd6a2');});}
function drawV13Effects(){for(const f of effects)if(f.type==='ghostlash'||f.type==='ghostpulse'){ctx.save();ctx.strokeStyle='#d7a7f4';ctx.lineWidth=5;if(f.type==='ghostlash'){for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(f.x,f.y-50);ctx.quadraticCurveTo(f.x+Math.cos(f.a)*80,f.y-80+i*25,f.x+Math.cos(f.a)*f.r,f.y+Math.sin(f.a)*f.r-60+i*20);ctx.stroke();}}else{ctx.beginPath();ctx.ellipse(f.x,f.y,Math.max(1,f.r*(1-f.t/f.max)),Math.max(1,f.r*.4*(1-f.t/f.max)),0,0,Math.PI*2);ctx.stroke();}ctx.restore();}for(const e of enemies)if(e.possessedTime>0){ctx.strokeStyle='#cda4ff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(e.x,e.y-35,60,65,0,0,Math.PI*2);ctx.stroke();txt('POSEÍDO',e.x,e.y-125,10,'#e8cbff');}if(zone===19){ctx.strokeStyle='#a7bedf66';ctx.lineWidth=1;for(let i=0;i<100;i++){const x=(i*149+clock*110)%WW,y=(i*77+clock*430)%WH;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-10,y+30);ctx.stroke();}if(Math.sin(clock*1.4)>.996){ctx.fillStyle='#c5d8ff55';ctx.fillRect(0,0,WW,WH);}}if(zone===22){const glow=fireForm(player)?310:145,g=ctx.createRadialGradient(player.x,player.y-45,60,player.x,player.y-45,glow);g.addColorStop(0,'#03010a00');g.addColorStop(1,'#03010a99');ctx.fillStyle=g;ctx.fillRect(0,0,WW,WH+140);}if(race==='osmo'&&ghostForm()&&player.ghostCorrupt>=70){ctx.fillStyle='rgba(23,0,35,'+((player.ghostCorrupt-70)/30*.72)+')';ctx.fillRect(0,0,WW,WH+140);}}
function hudV13(){if(player.watchOpen&&race==='omni')$('#talk').classList.add('hidden');const toggle=$('#cinematoggle');toggle.classList.toggle('hidden',race!=='omni'||player.alien||!player.watchOpen);text193(toggle,cinemaEnabled?'DESACTIVAR ANIMACIÓN / SONIDO':'ACTIVAR ANIMACIÓN / SONIDO');$('#watchclose').classList.toggle('hidden',race!=='omni'||player.alien||!player.watchOpen);$('#hauntaction').classList.toggle('hidden',!hospital());text193($('#hauntaction'),zone===19?'MISIÓN · HOSPITAL':zone===20?player.crouching?'LEVANTARSE':'AGACHARSE':zone===21?'INTERRUPTOR · E':'ENCENDER LUZ · E');$('#spectralbar').classList.toggle('hidden',!(race==='osmo'&&(ghostForm()||player.ghostLock>0))&&!hospital());if(hospital()){text193($('#mission .tiny'),'HOSPITAL · EXPEDICIÓN ESPECTRAL');text193($('#questtext'),player.haunt.complete?(player.ghostDNA?'ADN obtenido':'Derrota y escanea · ADN 20 %'):zone===20?'SIGILO · Evita a los guardias':zone===21?'Interruptores '+hauntWorld.switches.filter(Boolean).length+' / 3':zone===22?'Ilumina al espectro':'Misión disponible · Nivel 20');text193($('#questsub'),zone===20?'Cajas y pilares bloquean su visión':zone===21?'Ectoplasma y suelo frágil':zone===22?'Fuego o lámparas → forma sólida':'Hospital al norte de las Ruinas');text193($('#spectralbar'),zone===20?'DETECCIÓN '+Math.round(player.detection*100)+'% · '+(player.crouching?'AGACHADO':'DE PIE'):zone===21?'FASE 2 · APAGA LAS 3 MÁQUINAS':zone===22?'FASE 3 · ADN PARA AMBAS RAZAS':'INTERFERENCIA MAGNÉTICA EN EL INTERIOR');}if(interference()){$('#batteryfill').style.background=Math.floor(clock*5)%2?'#fa414a':'#701521';text193($('#batterytext'),'0%');text193($('#batteryhint'),'INTERFERENCIA · SIN FORMAS');}else $('#batteryfill').style.background='';if(race==='omni'&&!player.alien&&player.selected==='ghost'&&(!player.ghostDNA||player.level<20)){text193($('#transformhint'),'BLOQUEADO · MISIÓN HOSPITAL');text193($('#dialmastery'),'ADN ESPECTRAL PENDIENTE');}if(race==='osmo'&&(ghostForm()||player.ghostLock>0)){text193($('#spectralbar'),player.ghostLock>0?'ADN EN RECARGA · '+Math.ceil(player.ghostLock)+' s':'CORRUPCIÓN '+Math.floor(player.ghostCorrupt)+'%'+(player.ghostCorrupt>=70?' · ¡ALERTA! VUELVE A BASE':''));$('#spectralbar').style.background=player.ghostCorrupt>=70?'#762b54':'#372c53';if(ghostForm()){text193($('#transformlabel'),'VOLVER A BASE');text193($('#transformhint'),'CONTROLAR CORRUPCIÓN');text193($('#masterylabel'),'MAESTRÍA ESPECTRAL');}}}
function v13Receive(m){if(m.type==='warpRequest'&&net.role==='host'){if(m.zone===zone&&warpAllowedDestination(m.n)&&net.remote?.warps?.includes(m.n)&&!cinematic&&![20,21,22].includes(zone)&&player.regenWait<=0&&law.timer<=0&&!Object.values(net.members).some(o=>o.regenWait>0)){closeDialog();enterZone(m.n,'center');netUpdate(.2);}else lanSend({type:'warpDenied'});return true;}if(m.type==='warpDenied'){toast('Teletransporte no disponible: cierra menús y sal del combate');return true;}if(m.type==='hauntSwitch'&&net.role==='host'&&zone===21&&m.zone===21&&[0,1,2].includes(m.i)&&net.remote?.hauntPhase>=2&&dist(net.remote,SWITCHES[m.i])<100){hauntWorld.switches[m.i]=true;syncHauntProgress();netUpdate(.2);return true;}if(m.type==='hauntLamp'&&net.role==='host'&&zone===22&&m.zone===22&&[0,1].includes(m.i)&&dist(net.remote,LAMPS[m.i])<125){hauntWorld.lamps[m.i]=12;return true;}if(m.type==='ghostVictory'&&net.role==='guest'&&zone===22){ghostVictory();return true;}if(m.type==='possess'&&net.role==='host'&&m.zone===zone&&m.seq>net.seen&&ghostForm(net.remote)){net.seen=m.seq;const e=enemies.find(e=>e.id===m.id);if(e?.alive&&!e.guard&&!e.possessedBy&&!(e.hexBoss&&e.shield>0)&&!(e.ghostBoss&&e.immune)&&dist(e,net.remote)<290){e.possessedBy='guest';e.possessedPeer=net.sourcePeer;e.possessedTime=(e.hexBoss||e.majorBoss||e.wolfBoss||e.robotBoss||e.chapter2||e.ghostBoss)?2.3:4.3;}return true;}if(m.type==='releasePossession'&&net.role==='host'){const e=enemies.find(e=>e.id===m.id&&e.possessedBy==='guest'&&e.possessedPeer===net.sourcePeer);if(e){e.possessedBy=null;e.possessedTime=0;}return true;}return false;}
