function interaction17(){if(!started)return null;
 if(false&&dist(player,points17.casinoDoor)<100)return {label:'ENTRAR AL CASINO',action:()=>travelCasino17()};
 if(zone===V17.casino){for(const [key,label,action] of [['cashier','VERA · CAMBIAR FICHAS',cashier17],['slots','TRAGAPERRAS',()=>casinoTable17('slots')],['roulette','RULETA · LÍA',()=>casinoTable17('roulette')],['dice','DADOS · NPC',()=>casinoTable17('dice')]])if(dist(player,points17[key])<120)return {label,action};}
 if(zone===V17.plant)return {label:'MISIÓN · CENTRAL NUCLEAR',action:nuclearBrief17};
 if(zone===V17.intake&&dist(player,points17.component)<125)return {label:player.nuclear.stage<2?'RECOGER COMPONENTE':'EXAMINAR TUBERÍA',action:triggerSpill17};
 if(zone===V17.core&&dist(player,points17.gate)<120&&!player.nuclear.gate)return {label:'CORROER CERROJO',action:()=>{if(race!=='osmo'||player.form!=='acid'){toast('Necesitas tu cuerpo corrosivo');return;}player.nuclear.gate=true;player.nuclear.stage=4;burst(points17.gate.x,points17.gate.y-50,24,'#aaff47');shake=.2;save();toast('Cerrojo disuelto · desactiva la fuga al otro lado');}};
 if(zone===V17.core&&dist(player,points17.console)<115)return {label:'ESTABILIZAR REACTOR',action:completeNuclear17};return null;
}
const interactBase17=interact;
