const enterBase17=enterZone;
enterZone=function(next,side){if(!REGIONS[next])return false;if(next>=V17.plant&&next<=V17.core&&net.role){toast('La misión nuclear se juega en modo individual');return false;}if(next>=V17.intake&&next<=V17.core&&(race!=='osmo'||player.level<10||!player.nuclear?.stage)){toast('Acepta la misión en la periferia · Osmosiano nivel 10');return false;}if(zone===V17.intake&&next===V17.plant&&player.nuclear.stage>=2&&!player.nuclear.complete){toast('La tubería bloquea el regreso · avanza a Contención');return false;}if(next===V17.spill&&player.nuclear.stage<2){toast('Primero recoge el componente energético');return false;}if(next===V17.core&&!player.nuclear.acid){toast('Asimila el ácido antes de avanzar');return false;}if(zone===V17.core&&next===V17.plant&&!player.nuclear.complete){toast('Estabiliza el reactor para abrir la salida de emergencia');return false;}const ok=enterBase17(next,side);if(ok){scan17=null;absorbHold17=0;holdingAcid17=false;if(next===V17.spill&&side!=='right')player.x=260;if(next===V17.core&&side!=='right')player.x=160;for(let i=scanCorpses17.length-1;i>=0;i--)if(scanCorpses17[i].zone!==zone)scanCorpses17.splice(i,1);applyTheme17();}return ok;};
