function dayCasino17(){const c=player.casino,d=new Date().toISOString().slice(0,10);if(c.day!==d){c.day=d;c.bought=0;c.staked=0;}return c;}
function cashChange17(n){const c=dayCasino17();if(!Number.isSafeInteger(n)||!n)return false;if(n>0){if(player.coins<n||c.bought+n>300){toast('Saldo insuficiente o límite diario de 300 fichas');return false;}player.coins-=n;c.chips+=n;c.bought+=n;}else{if(c.chips<-n)return false;c.chips+=n;player.coins-=n;}persistGame();return true;}
function cashier17(){const c=dayCasino17();showDialog('VERA · CAJA DEL CASINO','Monedas por fichas','<p>«Una moneda, una ficha. Puedes canjear tus fichas de vuelta cuando quieras.»</p><div class="bank17"><b>'+player.coins+' monedas</b><b>'+c.chips+' fichas</b></div><p>Compra diaria: '+c.bought+'/300. Apuestas diarias: '+c.staked+'/500. Máximo 50 fichas por ronda. Sin compras con dinero real.</p><p>El azar también produce pérdidas. Ningún NPC ni dificultad cambia las probabilidades anunciadas.</p>',[['COMPRAR 10',()=>{cashChange17(10);cashier17();}],['COMPRAR 50',()=>{cashChange17(50);cashier17();}],['CANJEAR 10',()=>{cashChange17(-10);cashier17();}],['CANJEAR TODO',()=>{cashChange17(-c.chips);cashier17();}],['MESAS',casinoLobby17],['CERRAR',closeDialog]]);}
const casinoModes17=[{name:'Práctica · sin fichas',bet:0,npc:'Nico'},{name:'Tranquilo · 10 fichas',bet:10,npc:'Lía'},{name:'Normal · 20 fichas',bet:20,npc:'Bruno'},{name:'Alto · 50 fichas',bet:50,npc:'Vega'}];
let casinoMode17=1,casinoBusy17=false,casinoTimer17=null;
function random17(){if(window.crypto?.getRandomValues){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296;}return Math.random();}
function casinoOutcome17(game,choice,rng=random17){if(game==='slots'){const r=rng();const mult=r<.45?0:r<.75?1:r<.93?2:r<.99?3:8;return {mult,text:mult===8?'777 · JACKPOT':mult===3?'★ ★ ★':mult===2?'◆ ◆ ◆':mult===1?'● ● —':'● ◆ ★'};}if(game==='roulette'){const n=Math.floor(rng()*37),red=[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36].includes(n);return {mult:choice==='7'?(n===7?36:0):(n!==0&&(choice==='red'?red:!red)?2:0),text:n+' · '+(n===0?'VERDE':red?'ROJO':'NEGRO')};}const a=1+Math.floor(rng()*6),b=1+Math.floor(rng()*6),c=1+Math.floor(rng()*6),d=1+Math.floor(rng()*6);return {mult:a+b===c+d?1:a+b>c+d?1.9:0,text:'Tú: '+a+' + '+b+' · NPC: '+c+' + '+d};}
function casinoSettle17(game,choice,bet,rng=random17){const c=dayCasino17();if(!['slots','roulette','dice'].includes(game)||![0,10,20,50].includes(bet)||game==='roulette'&&!['red','black','7'].includes(choice))return null;if(c.chips<bet||c.staked+bet>500)return null;const out=casinoOutcome17(game,choice,rng),paid=Math.floor(bet*out.mult);c.chips+=paid-bet;c.staked+=bet;c.rounds++;c.net+=paid-bet;c.last={game,text:out.text,bet,paid,practice:bet===0};persistGame();return c.last;}
function casinoLobby17(){showDialog('BAHÍA · CLUB DE LA SUERTE','Elige tu mesa','<p>Prueba sin fichas o elige apuestas de 10, 20 o 50. Las dificultades cambian la apuesta y el rival, no tu suerte.</p>',[['TRAGAPERRAS',()=>casinoTable17('slots')],['RULETA CON LÍA',()=>casinoTable17('roulette')],['DADOS CONTRA NPC',()=>casinoTable17('dice')],['CAJA · VERA',cashier17],['CERRAR',closeDialog]]);}
function casinoTable17(game){if(casinoBusy17)return;const c=dayCasino17(),rules=game==='slots'?'<b>Pagos totales:</b> 0× (45 %), 1× (30 %), 2× (18 %), 3× (6 %), 8× (1 %). Retorno medio: 92 %.':game==='roulette'?'<b>37 casillas equiprobables.</b> Rojo/negro: 18/37, pago total 2×. Número 7: 1/37, pago total 36×. El cero pierde las apuestas de color. Retorno: 97,30 %.':'<b>Dos dados justos por persona.</b> Mayor suma gana: 44,37 %, pago 1,9×. Empate: 11,27 %, devolución. Derrota: 44,37 %. Retorno: 95,56 %.';const last=c.last;showDialog('CASINO · '+c.chips+' FICHAS',game==='slots'?'Tragaperras · Neón':game==='roulette'?'Ruleta · Lía':'Dados · '+casinoModes17[casinoMode17].npc,'<div class="casino-screen17" id="casinoscreen17">'+(last?.game===game?last.text:'◆  ★  7')+'</div><p id="casinoresult17">'+(last?.game===game?(last.practice?'Práctica':last.paid+' fichas devueltas · resultado neto '+(last.paid-last.bet)):'Todos los resultados dependen del azar.')+'</p><div class="casino-modes17">'+casinoModes17.map((m,i)=>'<button data-mode17="'+i+'" class="'+(i===casinoMode17?'active':'')+'">'+m.name+'</button>').join('')+'</div><p>'+rules+'</p><p>Los pagos incluyen la apuesta. Quedan '+(500-c.staked)+' fichas de apuestas hoy.</p>',[...(game==='roulette'?[['ROJO',()=>casinoPlay17(game,'red')],['NEGRO',()=>casinoPlay17(game,'black')],['NÚMERO 7',()=>casinoPlay17(game,'7')]]:[['JUGAR · '+casinoModes17[casinoMode17].bet+' FICHAS',()=>casinoPlay17(game,'')]]),['OTRA MESA',casinoLobby17],['CAJA',cashier17],['SALIR',closeDialog]]);document.querySelectorAll('[data-mode17]').forEach(b=>b.onclick=()=>{casinoMode17=Number(b.dataset.mode17);casinoTable17(game);});}
function casinoPlay17(game,choice){if(casinoBusy17||zone!==V17.casino||net.role)return;const result=casinoSettle17(game,choice,casinoModes17[casinoMode17].bet);if(!result){toast('Fichas insuficientes o límite diario alcanzado');return;}casinoBusy17=true;const screen=$('#casinoscreen17');screen?.classList.add('spinning17');if(screen)screen.textContent='7 ◆ ★';document.querySelectorAll('#dialogbuttons button,[data-mode17]').forEach(b=>b.disabled=true);casinoTimer17=setTimeout(()=>{casinoBusy17=false;casinoTimer17=null;if(dialogOpen&&zone===V17.casino)casinoTable17(game);},850);}
function nuclearBrief17(){showDialog('PERIFERIA · OSMOSIANO · NIVEL 10','El componente energético','<p>Un componente de la central podría estabilizar tus absorciones. Entra por Admisión, recógelo y busca una salida.</p><p>Estado: '+(player.nuclear.complete?'Central estabilizada. Absorción ácida permanente.':player.nuclear.stage?'Misión en curso; puedes retomar tu avance.':'Pendiente')+'</p><p>Recompensa: forma ácida, 350 de vida base, seis técnicas entre maestría y árbol; las mejoras de vitalidad de Ten también se aplican.</p>',[...(race==='osmo'&&player.level>=10?[['ENTRAR',()=>{player.nuclear.stage=Math.max(1,player.nuclear.stage);persistGame();closeDialog();enterZone(V17.intake,'center');}]]:[]),['CERRAR',closeDialog]]);}
function triggerSpill17(){if(race!=='osmo'||player.level<10||player.nuclear.stage<1)return;if(player.nuclear.stage>=2){toast('El retorno está bloqueado. Avanza por la derecha.');return;}player.nuclear.stage=2;shake=.6;burst(1000,500,50,'#b8ff43');persistGame();showDialog('ALARMA · FALLO DE CONTENCIÓN','La tubería estalla','<p>Consigues el componente, pero una tubería revienta. La compuerta de regreso se cierra y el ácido inunda Contención.</p><p>Al este hay una plataforma segura y un robot de mantenimiento corroído. Tendrás que aprender a resistir el líquido.</p>',[['BUSCAR SALIDA',()=>{closeDialog();enterZone(V17.spill,'left');}]]);}
function unlockAcid17(){if(race!=='osmo'||player.level<10||zone!==V17.spill||player.nuclear.stage<2)return false;player.nuclear.acid=true;player.nuclear.stage=Math.max(3,player.nuclear.stage);player.absorbUnlocks.acid=true;absorbHold17=0;holdingAcid17=false;player.battery=Math.max(35,player.battery);absorbAcid17();visual17={kind:'acid',t:0,max:2.4};save();toast('¡ÁCIDO ASIMILADO! Ya puedes cruzar el líquido verde');return true;}
function absorbAcid17(){if(race!=='osmo'||!player.nuclear.acid||player.level<10){toast('Completa la absorción en la central · nivel 10');return false;}if(interference()||player.battery<=0){toast('Necesitas energía y una zona sin interferencia');return false;}const ratio=player.hp/maxHP();endGhost();player.form='acid';player.fireCharge=0;player.alien=false;player.activeAlien=player.selected='osmo';refreshOsmo();player.cool=player.cooldowns.acid;player.hp=clamp(ratio*maxHP(),1,maxHP());closeDialog();burst(player.x,player.y-60,24,'#b2ff43');save();return true;}
const absorbBase17=absorb;
absorb=function(form){if(form==='acid')return absorbAcid17();const changed=player.form!==form,ok=absorbBase17(form);if(ok&&form==='fire'&&changed&&cinemaEnabled){cinematic={mode:'movie',id:'osmofire17',time:0,hold:false,osmo:true};paused=true;document.body.classList.add('cinema');window.OmniSound?.sample('heatblast');window.OmniMusic?.pauseForEvent();resetInput();}return ok;};
const absorptionBase17=absorptionMenu;
absorptionMenu=function(){absorptionBase17();const b=document.createElement('button');b.textContent=player.nuclear.acid?'FORMA ÁCIDA · 350 VIDA':'ÁCIDO · MISIÓN CENTRAL NV.10';b.onclick=()=>absorb('acid');$('#dialogbuttons').prepend(b);};
function completeNuclear17(){const q=player.nuclear;if(race!=='osmo'||player.level<10||!q.acid||!q.gate||q.complete)return;if(player.form!=='acid'){toast('Usa tu cuerpo ácido para sabotear los circuitos');return;}q.complete=true;q.stage=5;player.coins+=25;xp(300);save();showDialog('MISIÓN COMPLETADA','Contención restablecida','<p>Disuelves los circuitos de emergencia, detienes la fuga y abres la salida. Conservas permanentemente la absorción de ácido.</p><p>+300 EXP · +25 monedas. Visita a Ten para mejorar tu vitalidad; entrena esta forma para abrir sus cuatro técnicas y compra dos adicionales en el árbol.</p>',[['SALIR A LA PERIFERIA',()=>{closeDialog();enterZone(V17.plant,'center');}],['EXPLORAR',closeDialog]]);}
const solidBase17=isSolid;
isSolid=function(x,y,...args){if(zone===V17.core&&!player.nuclear?.gate&&x>690&&x<790)return true;return solidBase17(x,y,...args);};
const osmoAttackBase17=osmoAttack;
osmoAttack=function(i){if(player.form!=='acid')return osmoAttackBase17(i);if(!unlockedSkill('acid',i)){toast(i<4?'Requiere maestría ácida '+OSMO_SKILLS.acid[i].unlock:'Aprende esta técnica en el árbol');return;}const s=OSMO_SKILLS.acid[i],t=nearest(450),a=t?Math.atan2(t.y-player.y,t.x-player.x):Math.atan2(player.dy,player.dx),d=s.damage*multiplier();player.cool[i]=s.cd;player.attack=[.55,.7,.8,1.1,.85,.9][i];player.acidCast17={i,t:player.attack,max:player.attack};player.acidPose=i;player.face=Math.cos(a)>=0?1:-1;const x=t?.x??player.x+player.face*140,y=t?.y??player.y;
 if(i===0){effects.push({type:'acidSlash17',x:player.x+player.face*45,y:player.y-40,r:95,t:.5,max:.5});areaHit(player.x+player.face*50,player.y,100,d,.2);}
 if(i===1){shoot('goo',a,d,440);effects.push({type:'acidLance17',x:player.x,y:player.y-60,a,r:150,t:.45,max:.45});}
 if(i===2)effects.push({type:'acidPool17',x,y,r:145,t:4,max:4,tick:0,damage:d});
 if(i===3){effects.push({type:'acidBurst17',x:player.x,y:player.y,r:210,t:1,max:1});areaHit(player.x,player.y,210,d,.5);shake=.25;}
 if(i===4){effects.push({type:'acidGeyser17',x,y,r:120,t:.9,max:.9});areaHit(x,y,125,d,.5);}
 if(i===5){player.shield=110*healthFactor();player.shieldTime=7;effects.push({type:'acidArmor17',x:player.x,y:player.y,r:100,t:1,max:1});areaHit(player.x,player.y,110,d,.3);}tone(220+i*55,.13,'triangle');};
// Scanning is a separate, single attempt after victory; no rerolls on reload.
const wolfRewardBase17=wolfReward,ghostVictoryBase17=ghostVictory;
wolfReward=function(b,roll){if(net.role)return wolfRewardBase17(b,roll);if(!b.alive)return;b.alive=false;b.hp=0;player.wolfTimer=60;if(player.level>=30)xp(900);else toast('Blitztwolfer · recompensas desde nivel 30');if(race==='omni'&&player.level>=30)addScan17('wolf',b);burst(b.x,b.y-55,25,'#d5e9ff');save();};
ghostVictory=function(){if(net.role||race==='osmo')return ghostVictoryBase17();if(player.level<20||player.haunt.phase<3)return;if(!player.haunt.complete){player.haunt.complete=true;xp(650);player.coins+=10;}const b=enemies.find(e=>e.ghostBoss);if(b)addScan17('ghost',b);save();};
function addScan17(id,b){const existing=scanCorpses17.find(s=>s.id===id&&s.zone===zone);if(existing)scanCorpses17.splice(scanCorpses17.indexOf(existing),1);scanCorpses17.push({id,x:b.x,y:b.y,face:b.face,zone,ttl:12,used:false});toast(ALIENS[id].name+' debilitado · acércate y ESCANEA en 12 s · ADN 20 %');}
function nearestScan17(){return race==='omni'&&!net.role?scanCorpses17.find(s=>!s.used&&s.zone===zone&&s.ttl>0&&dist(player,s)<260&&lineClear(player.x,player.y,s.x,s.y)):null;}
function startScan17(){if(!started||paused||scan17||cinematic)return false;const s=nearestScan17();if(!s||player.level<(s.id==='wolf'?30:20))return false;if(player.alien)revert(false);s.used=true;const success=(s.id==='ghost'&&(player.scans.ghost?.attempts||0)>=14)||random17()<.2;player.scans[s.id]={attempts:(player.scans[s.id]?.attempts||0)+1,lastSuccess:success};if(success){if(s.id==='wolf')player.wolfDNA=true;else player.ghostDNA=true;}scan17={...s,t:0,max:2.1,success};player.face=s.x>=player.x?1:-1;player.watchOpen=false;resetInput();cam.x=clamp((player.x+s.x)/2-W*.5/sceneZoom(),0,cameraMaxX());cam.y=clamp(player.y-H*.64/sceneZoom(),0,cameraMaxY());hud();persistGame();return true;}
