function introStart21(b){intro21={t:5,max:5,x:b.x,y:b.y,startX:cam.x,startY:cam.y};b.introDone21=true;resetInput();}
function introUpdate21(dt){if(!intro21)return false;if(net.role!=='guest')intro21.t=Math.max(0,intro21.t-dt);else intro21.t=Math.max(0,intro21.t-dt);const p=1-intro21.t/intro21.max,targetX=clamp(intro21.x-W/sceneZoom()*.5,0,cameraMaxX()),targetY=clamp(intro21.y-H/sceneZoom()*.55,0,cameraMaxY());cam.x+=(targetX-cam.x)*Math.min(1,dt*3);cam.y+=(targetY-cam.y)*Math.min(1,dt*3);resetInput();player.moving=false;hud();if(intro21.t<=0){intro21=null;cam.x=clamp(player.x-W*.48/sceneZoom(),0,cameraMaxX());cam.y=(zone===CITY21?cityCameraY22():clamp(player.y-H*.61/sceneZoom(),0,cameraMaxY()));}return true;}
const updateBase21=update;update=function(dt){if(zone===CITY21&&started&&!paused&&!cinematic&&!document.hidden){if(introUpdate21(dt))return;const b=ensureClancy21();if(b?.alive&&!b.introDone21&&activeClancy21().some(p=>dist(p,b)<650)){introStart21(b);return;}if(net.role!=='guest'){cityTime21=(cityTime21+dt*144)%86400;updateCars21(dt);}const scaled=race==='omni'&&!player.alien&&player.watchOpen?dt*.08:dt;updateClancy21(scaled);}updateBase21(dt);};
const drawBase21=draw;draw=function(){drawBase21();if(intro21){ctx.save();ctx.fillStyle='#030708e6';ctx.fillRect(0,0,W,65);ctx.fillRect(0,H-80,W,80);txt('CLANCY · EL CONTROLADOR DE INSECTOS',W/2,34,18,'#d3ef9d');txt(intro21.t>2.5?'«Nos quieren echar de nuestra casa... Bellwood pagará.»':'Seis avispas protegen a Clancy. Aléjate cuando prepare el empuje.',W/2,H-46,12,'#e3e8ca');txt('DOBLE TOQUE PARA SALTAR',W/2,H-18,9,'#a5c39c');ctx.restore();}};
let lastIntroTap21=0;canvas.addEventListener('pointerdown',()=>{if(!intro21)return;const now=performance.now();if(now-lastIntroTap21<400){if(net.role==='guest')lanSend({type:'skipClancy21',zone:CITY21});else intro21.t=0;}lastIntroTap21=now;});
function nearTen21(){return zone===9&&dist(player,ten)<140;}
function startClancy21(){const q=player.clancy21;if(!nearTen21()||player.level<35||q.completions>=2||['active','return'].includes(q.state))return false;q.state='active';q.run=String(Date.now())+'-'+Math.floor(random17()*1e9);q.intro=false;if(net.role==='guest')lanSend({type:'clancyStart21',zone:9,run:q.run});closeDialog();persistGame();toast('Clancy · entra a Bellwood desde las Ruinas del Pilar · busca la avenida central');return true;}
function claimClancy21(){const q=player.clancy21;if(!nearTen21()||q.state!=='return'||q.completions>=2)return false;const gain=q.rewarded?0:Math.max(0,Math.min(2,40-player.level));if(gain){const ratio=player.xp/xpNeed();player.level+=gain;player.points+=gain;player.xp=player.level===100?0:Math.floor(ratio*xpNeed());burst(player.x,player.y-40,35,'#c3ff8a');tone(880,.25);}q.rewarded=true;q.completions++;q.state=q.completions>=2?'complete':'done';closeDialog();persistGame();toast(gain?'Clancy completado · +'+gain+' niveles': 'Repetición completada · sin EXP');return true;}
function clancyTalk21(){const q=player.clancy21;showDialog('TEN · HISTORIA 04 · NIVEL 35','El enjambre de Bellwood','<p>«Clancy controla insectos y ha tomado la avenida central. La demolición de su edificio lo enfureció. Sus avispas mutantes atacan a los vecinos. Necesito que lo detengas.»</p><p>Clancy: 4000 vida · seis avispas de 500 vida. Lanzan aguijones venenosos. El empuje de Clancy impide quedarse pegado a él. Tras eliminar las seis, tarda 30 segundos en invocar otra oleada.</p><p>Entrada: al oeste de las Ruinas del Pilar. Busca la intersección del centro de Bellwood.</p><p>'+(q.state==='return'?'Victoria confirmada · cobra con Ten.':q.state==='active'?'Misión activa · puedes volver a intentarlo si caes.':q.completions>=2?'Primera victoria y única repetición completadas.':q.rewarded?'Una repetición disponible · sin experiencia.':'+2 niveles y +2 puntos al cobrar por primera vez, hasta el máximo de nivel 40.')+'</p>',[...(q.state==='return'&&nearTen21()?[['COBRAR',claimClancy21]]:[]),...(nearTen21()&&player.level>=35&&q.completions<2&&!['active','return'].includes(q.state)?[['ACEPTAR',startClancy21]]:[]),['VOLVER',chaptersMenu]]);}
function storyObject21(id){return player[['story','story2','story3'][id]];}
function canReplayChapter21(id){const q=storyObject21(id);return nearTen21()&&!['active','return'].includes(q.state)&&player.level>=[1,20,30][id]&&(id===0||id===1&&player.story.rewarded21||id===2&&player.story2.rewarded21);}
