const words23={log:L23('NOVEDADES','UPDATE LOG','NOVIDADES','GÜNCELLEME NOTLARI'),back:L23('VOLVER','BACK','VOLTAR','GERİ'),close:L23('CERRAR','CLOSE','FECHAR','KAPAT'),story:L23('VER HISTORIA','WATCH STORY','VER HISTÓRIA','HİKÂYEYİ İZLE'),read:L23('LEER HISTORIA','READ STORY','LER HISTÓRIA','HİKÂYEYİ OKU'),skip:L23('DOBLE TOQUE PARA SALTAR','DOUBLE TAP TO SKIP','TOQUE DUAS VEZES PARA PULAR','ATLAMAK İÇİN İKİ KEZ DOKUN'),ball:L23('FORMA BOLA','BALL FORM','FORMA BOLA','TOP FORMU'),normal:L23('FORMA NORMAL','NORMAL FORM','FORMA NORMAL','NORMAL FORM'),armor:L23('BLINDAJE','ARMOR','BLINDAGEM','ZIRH'),newDNA:L23('¡ADN CANNONBOLT DESBLOQUEADO!','CANNONBOLT DNA UNLOCKED!','DNA CANNONBOLT DESBLOQUEADO!','CANNONBOLT DNA AÇILDI!'),fail:L23('FALLO DEL OMNITRIX','OMNITRIX MALFUNCTION','FALHA DO OMNITRIX','OMNITRIX ARIZASI'),chance:L23('ADN 10 % por transformación válida','DNA 10% per successful transformation','DNA 10% por transformação válida','Başarılı dönüşüm başına %10 DNA'),master:L23('Requiere maestría','Requires mastery','Requer maestria','Ustalık gerekli')};
// Static packaged portraits work under file:///android_asset without canvas reads.
pediaIcon18=function(canvas,row,known,form){
 const img=document.createElement('img');
 img.className='pedia-portrait23';
 img.width=80;img.height=90;img.draggable=false;
 img.alt=canvas.parentElement.querySelector('b')?.textContent||'Omnipedia';
 img.src='assets/omnipedia24/'+row+'-'+(form||'base')+'-'+(known?'known':'locked')+'.webp';
 canvas.replaceWith(img);
};
ALIENS.cannonbolt={name:'Cannonbolt',row:109,hp:340,color:'#f8cf3f',skills:[makeSkill('Aplastamiento','APLASTAR',58,6),makeSkill('Coraza (pasiva)','CORAZA',0,0),makeSkill('Embestida ígnea','EMBESTIR',76,8,40),makeSkill('Rebotes constantes','REBOTES',24,18,75),{...makeSkill('Giro sísmico','GIRO',92,12),points:3},{...makeSkill('Guardia acorazada','GUARDIA',0,20),points:3}]};CORE_ALIENS.push('cannonbolt');SPEEDS.cannonbolt=190;
