const initBase23=initProgress;initProgress=function(){initBase23();player.cannonDNA=!!player.cannonDNA;player.cannonArmor23=clamp(Number.isFinite(player.cannonArmor23)?player.cannonArmor23:100,0,100);player.cannonWait23=Math.max(0,Number(player.cannonWait23)||0);player.cannonBall23=!!player.cannonBall23&&race==='omni'&&player.alien&&player.activeAlien==='cannonbolt';player.cannonCast23=null;player.cannonTurn23=0;player.cannonAttempts23=Math.max(0,Number(player.cannonAttempts23)||0);};
