const poseBase23=combatPose;combatPose=function(o,row,f){if(!cannonForm23(o))return poseBase23(o,row,f);const a=o.cannonCast23,p=a?clamp(1-a.t/a.max,0,1):0,ball=!!o.cannonBall23;let frame=ball?12+(o.moving?Math.floor(o.cannonTurn23||0)%4:0):o.moving?walkFrame166(o,4,Math.floor(o.anim||0)%4):0,lift=0;if(a){if(a.i===0){frame=(ball?[16,17,18,19]:[6,7,8,9])[Math.min(3,Math.floor(p*4))];lift=Math.sin(p*Math.PI)*150;}else if(a.i===2)frame=ball?20:5;else if(a.i===3){frame=ball?16+Math.min(3,Math.floor((a.max-a.t)%1*4)):7;lift=Math.abs(Math.sin((a.max-a.t)*Math.PI*2))*105;}else if(a.i===4)frame=ball?21+Math.min(2,Math.floor(p*3)):4+Math.floor(p*2);else if(a.i===5)frame=ball?12:10;else frame=ball?12:4;}return {row:109,f:frame,lift};};
