const ITEM28={suit:{name:'Traje Plomero anticorrodium',price:500,description:'+150 vida en forma base. Protección contra Corrodium. No aumenta la vida de aliens ni transformaciones.'},medkit:{name:'Botiquín',price:35,description:'Recupera 60 de vida; se consume al usarlo.'},energy:{name:'Reserva energética',price:30,description:'Recupera 25 de batería, tinta o maná; se consume al usarla.'}};
function initInventory28(){player.inventory28=Object.assign({suit:0,medkit:0,energy:0},player.inventory28||{});for(const k of Object.keys(ITEM28))player.inventory28[k]=clamp(Math.floor(Number(player.inventory28[k])||0),0,k==='suit'?1:99);player.suitEquipped28=!!player.suitEquipped28&&!!player.inventory28.suit;player.kai28=Object.assign({state:'new',claimed:false,seen:{}},player.kai28||{});player.healCool28=Math.max(0,Number(player.healCool28)||0);player.solarCool28=Math.max(0,Number(player.solarCool28)||0);}
const initBase28=initProgress;initProgress=function(){initBase28();initInventory28();player.solarCast28=null;player.hp=clamp(player.hp,1,maxHP());};
function baseForm28(o=player){const r=o===player?race:o.race;return r==='omni'?!o.alien:r==='osmo'?o.form==='human':!o.racePower26;}
function suitOn28(o=player){return !!o.suitEquipped28&&baseForm28(o);}
const maxBase28=maxHP;maxHP=function(){return maxBase28()+(suitOn28()?150:0);};
function equipSuit28(on){initInventory28();if(!player.inventory28.suit)return false;const ratio=player.hp/maxHP();player.suitEquipped28=!!on;player.hp=clamp(ratio*maxHP(),1,maxHP());save();hud();return true;}
function buyItem28(id){initInventory28();const item=ITEM28[id];if(zone!==SHOP28||dist(player,bouman28)>160||!item||player.coins<item.price||player.inventory28[id]>=(id==='suit'?1:['medkit','energy'].includes(id)?3:99))return false;player.coins-=item.price;player.inventory28[id]++;save();return true;}
function useItem28(id){initInventory28();if(!player.inventory28[id]||!['medkit','energy'].includes(id))return false;if(id==='medkit'){if(player.hp>=maxHP())return false;player.hp=Math.min(maxHP(),player.hp+60);}else{if(newRace26()){if(player.raceResource26>=manaCap205())return false;player.raceResource26=Math.min(manaCap205(),player.raceResource26+25);player.battery=player.raceResource26;}else{if(player.battery>=100)return false;player.battery=Math.min(100,player.battery+25);}}player.inventory28[id]--;save();return true;}
function inventoryMenu28(){initInventory28();showDialog('BOUMAN · '+race.toUpperCase(),'Mochila · '+player.coins+' monedas','<p>Objetos de esta raza. El traje aporta exactamente 150 de vida adicional en forma base.</p><div class="racecards">'+Object.entries(ITEM28).map(([id,it])=>'<button class="racecard" data-item28="'+id+'"><b>'+it.name+'</b><p>'+it.description+'</p><small>'+player.inventory28[id]+' · '+(id==='suit'?(player.suitEquipped28?'EQUIPADO · DESEQUIPAR':'EQUIPAR'):'USAR')+'</small></button>').join('')+'</div>',[['CERRAR',closeDialog]]);document.querySelectorAll('[data-item28]').forEach(b=>b.onclick=()=>{const id=b.dataset.item28;if(id==='suit')equipSuit28(!player.suitEquipped28);else useItem28(id);inventoryMenu28();});}
function boumanTalk28(){initInventory28();showDialog('SR. BOUMAN · BELLWOOD','Mercado de Bouman · '+player.coins+' monedas','<p>«Bienvenido. Tus compras pertenecen a tu raza actual.»</p><div class="racecards">'+Object.entries(ITEM28).map(([id,it])=>'<button class="racecard" data-buy28="'+id+'"><b>'+it.name+'</b><p>'+it.description+'</p><small>'+it.price+' monedas · '+player.inventory28[id]+(['medkit','energy'].includes(id)?' / 3':'')+' en mochila</small></button>').join('')+'</div>',[['MOCHILA',inventoryMenu28],['CERRAR',closeDialog]]);document.querySelectorAll('[data-buy28]').forEach(b=>b.onclick=()=>{if(!buyItem28(b.dataset.buy28))toast(['medkit','energy'].includes(b.dataset.buy28)&&player.inventory28[b.dataset.buy28]>=3?'Máximo 3 de este consumible; úsalo para comprar más':'Monedas insuficientes o ya tienes este objeto');boumanTalk28();});}
