function kaiTalk28(){initInventory28();const q=player.kai28;showDialog('KAI GREEN · NV.36','El guardián del bosque','<p>«Un aullido recorre este bosque. Derrota a Blitztwolfer y vuelve a hablar conmigo.»</p><p>700 EXP en la primera entrega. '+(player.level<36?'Necesitas nivel 36.':q.state==='active'?'Objetivo: derrotar a Blitztwolfer.':q.state==='complete'?'Misión completada.':'')+'</p>',[...(q.state==='new'&&player.level>=36?[['ACEPTAR',()=>{q.state='active';q.seen={};closeDialog();save();}]]:[]),...(q.state==='return'&&!q.claimed?[['COBRAR · 700 EXP',()=>{if(q.state!=='return'||q.claimed)return;q.claimed=true;q.state='complete';xp(700);closeDialog();save();}]]:[]),['CERRAR',closeDialog]]);}
const wolfBase28=wolfReward;wolfReward=function(b,...args){const alive=b.alive;wolfBase28(b,...args);if(alive&&!b.alive){const token='wolf28:'+Date.now();kaiVictory28(token);if(net.role==='host')lanSend({type:'kaiVictory28',zone:17,token});}};
