function drawBoss53(e){const c=e.cast53,f=c?c.type==='punch'?4:c.type==='sweep'?5:6:e.moving?Math.floor(e.anim)%4:7;const lift=c?.type==='slam'?Math.sin(clamp(1-c.t/c.max,0,1)*Math.PI)*70:0;sprite(280,f,e.x,e.y-lift,270,e.face,e.hit>0?.6:1);txt('VILGAX · '+Math.ceil(e.hp)+' / '+e.max,e.x,e.y-295,12,'#ffe0b5');ctx.fillStyle='#241b1b';ctx.fillRect(e.x-85,e.y-283,170,8);ctx.fillStyle='#e98958';ctx.fillRect(e.x-85,e.y-283,170*clamp(e.hp/e.max,0,1),8);if(c&&!c.hit){ctx.strokeStyle='#ffb43b';ctx.lineWidth=3;ctx.setLineDash([7,7]);ctx.beginPath();ctx.ellipse(c.x,c.y,c.type==='slam'?290:c.type==='sweep'?220:145,45,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);}}
