function spawnRider90(now=Date.now()){if(zone!==HALL87||net.role==='guest')return null;const q=hall87();const live=enemies.find(e=>e.riderBoss90&&e.alive);if(live)return live;if((q.riderSpawnAt90||0)>now)return null;enemies=enemies.filter(e=>!e.riderBoss90);const e={id:'rider90',kind:'enemy',riderBoss90:true,balance88:true,halloween87:true,alive:true,x:1650,y:1510,homeX:1650,homeY:1510,hp:7000,max:7000,level:40,damage:50,reward:0,cd:3,chainCD:5,stareCD:8,bikeCD:12,stun:0,hit:0,anim:0,face:1,moving:false,bikeTime90:0};enemies.push(e);zoneStates[region().id]=enemies;return e;}
