function updateBurn90(dt){if(player.trauma90>0)player.trauma90=Math.max(0,player.trauma90-dt);const b=player.burn90;if(!b)return;if(zone!==b.zone||player.hp<=0){player.burn90=null;return;}const active=Math.min(dt,b.t);b.t-=dt;b.tick-=active;while(b.tick<=0){b.tick+=1;const burned93=burnDamage93(30);player.hp=Math.max(0,player.hp-burned93);player.regenWait=12;popup(player.x,player.y-110,'−'+burned93,'#ffb15a');if(player.hp<=0){player.burn90=null;player.trauma90=0;defeat();return;}}if(b.t<=1e-8)player.burn90=null;}
