phillTalk25=function(){const q=player.phill25,r=phillReward89(),near=zone===24&&dist(player,phill25)<145;showDialog('PHILL · '+T80('NV.30','LV.30','NV.30','SV.30'),T80('Patrulla del Vacío Nulo','Null Void Patrol','Patrulha do Vazio Nulo','Null Void Devriyesi'),'<div data-no-i18n><p>'+T80('Derrota siete bestias y vuelve con Phill.','Defeat seven beasts and return to Phill.','Derrote sete criaturas e volte a Phill.','Yedi yaratığı yen ve Phill’e dön.')+'</p><p>'+q.kills+' / 7 · '+r+' EXP · 53 '+T80('monedas','coins','moedas','para')+'</p><p>'+T80('3 entregas por nivel hasta NV.40; después la EXP queda fija. La EXP de enemigos suma aparte.','3 turn-ins per level up to LV.40; XP stays fixed afterwards. Enemy XP is additional.','3 entregas por nível até NV.40; depois a EXP fica fixa. EXP de inimigos soma à parte.','40. seviyeye kadar seviye başına 3 teslim; sonra deneyim sabit kalır. Düşman deneyimi ayrıca eklenir.')+'</p></div>',[...(near&&player.level>=30?(q.state==='return'?[[T80('COBRAR','CLAIM','RECEBER','AL')+' · '+r+' EXP',claimPhill90]]:q.state==='active'?[[T80('REPONER BESTIAS','REPLENISH BEASTS','REPOR CRIATURAS','YARATIKLARI YENİLE'),()=>{replenishPhill45();closeDialog();}]]:[[T80('ACEPTAR / REPETIR','ACCEPT / REPEAT','ACEITAR / REPETIR','KABUL / TEKRAR'),acceptPhill45]]):[]),[T80('CERRAR','CLOSE','FECHAR','KAPAT'),closeDialog]]);appendRestart67('phill');};
