 for(const e of enemies){if(!e.arena102||!e.alive)continue;e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);e.cd=Math.max(0,e.cd-dt);e.moving=false;if(e.stun>0||e.possessedTime>0)continue;const target=teamTargets().filter(t=>t.alive!==false).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)continue;const d=dist(e,target);e.face=target.x>=e.x?1:-1;
  if(e.cast102){const c=e.cast102;c.t-=dt;if(!c.hit&&c.t<=.15){c.hit=true;if(c.ranged){const angle=Math.atan2(target.y-e.y,target.x-e.x);hostileShots.push({type:'green',x:e.x,y:e.y-35,dx:Math.cos(angle)*250,dy:Math.sin(angle)*250,t:2.5,r:10,damage:e.damage,zone});}else if(dist(e,target)<(e.boss102?165:115)&&lineClear(e.x,e.y,target.x,target.y))hurtTeam(target,e.damage);burst(e.x+e.face*45,e.y-35,9,e.boss102?'#ffae69':'#c2ff8d');}if(c.t<=0)e.cast102=null;continue;}
  if(d<(e.ranged102?500:e.boss102?150:100)&&e.cd<=0&&lineClear(e.x,e.y,target.x,target.y)){e.cast102={t:.75,hit:false,ranged:e.ranged102&&d>120};e.cd=e.boss102?2.5:1.8;continue;}
  if(d>75){moveActor(e,(target.x-e.x)/d*105*dt,(target.y-e.y)/d*105*dt);e.moving=true;e.anim+=dt*7;}
 }
