function treeGlyph102(s,i){const n=s.name.toLowerCase();const paths=/fuego|llama|ígneo/.test(n)?'<path d="M30 7C35 19 20 20 32 34C39 27 40 22 41 18C59 40 42 55 29 55C13 55 5 38 20 23C19 35 25 39 28 38C18 22 30 21 30 7Z"/>':/vuelo|volar|ala/.test(n)?'<path d="M8 42Q11 14 51 9Q39 41 8 42ZM9 43L42 19"/>':/garra|rasgu|mord|arañ/.test(n)?'<path d="M10 51L23 9L18 43L33 8L29 43L45 9L41 45"/>':/agua|hidro|humedad|presión/.test(n)?'<path d="M30 6C25 18 14 26 14 36A16 16 0 0 0 46 36C46 26 35 18 30 6Z"/>':/escudo|coraza|pasiv/.test(n)?'<path d="M30 8L49 16V32Q46 45 30 53Q14 45 11 32V16ZM20 29L27 37L42 22"/>':/rayo|láser|pulso|eléct/.test(n)?'<path d="M35 6L14 33H29L23 54L47 25H32Z"/>':/tornado|órbita|remolino|giro|giratoria/.test(n)?'<path d="M8 15Q30 4 52 15Q30 26 8 15ZM13 26Q30 20 47 26L35 47H25ZM20 35H40"/>':/roca|diam|crist|lanza/.test(n)?'<path d="M30 6L48 22L38 50H21L12 22ZM12 22H48M30 6L23 22L30 50L37 22Z"/>':/saliva|ácid|charco|tinta|escup/.test(n)?'<path d="M30 7Q28 21 17 32Q7 46 25 51Q43 55 47 42Q47 35 37 28Q31 21 30 7Z"/>':/puño|golpe|martillo|aplauso/.test(n)?'<path d="M12 28V19L20 17L24 25V12H31V24L37 16L43 20L39 31L48 29V41L38 51H21L12 40Z"/>':['<path d="M9 43L44 11L29 40L51 28"/>','<circle cx="30" cy="30" r="19"/><path d="M4 30H56M30 4V56"/>','<path d="M11 49L30 10L49 49Z"/>','<path d="M9 30Q30 6 51 30Q30 54 9 30Z"/><circle cx="30" cy="30" r="8"/>','<path d="M8 45L25 14L33 35L50 15"/>','<circle cx="30" cy="30" r="21"/><path d="M15 30H45M30 15V45"/>'][i%6];return '<svg viewBox="0 0 60 60" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round">'+paths+'</svg>';}
