function upgradeTool125(){const s=local121();if(s.tier!==2||!tool107().owned||!NEW_PARTS125.every(k=>s.parts[k]>=1)||blocked112()||!pakmarVisible105()||dist(player,pakmar105)>150)return false;for(const k of NEW_PARTS125)s.parts[k]--;s.tier=3;save();hud();return true;}
const textBefore125=toolDescription107;toolDescription107=function(){const s=local121();return (s.tier===3?words97('Objeto permanente · nivel 3.','Permanent item · tier 3.','Item permanente · nível 3.','Kalıcı eşya · seviye 3.')+' '+words97('Materia Diamante, Fuego Acuático y Cuatro Insecotide.','Diamond Matter, Aquatic Fire and Four Stinkfly.','Matéria Diamante, Fogo Aquático e Quatro Insectóide.','Elmas Madde, Su Ateşi ve Dört Kokarca.'):textBefore125())+' '+words97('Nivel 3: conserva las fusiones anteriores y añade Cuatro Insecotide durante 200 s, con reutilización de 100 s. Solo Omnitrix prototipo. Requiere nivel 2 y una Cápsula de esporas (cap.19/nv.40), una Aleación del Vacío (cap.20/nv.41) y un Núcleo galáctico (cap.21/nv.50). Cada material tiene 50% por victoria completa, por participante y raza; las vistas previas no dan materiales.','Tier 3 keeps prior fusions and adds Four Stinkfly for 200 s, with 100 s reuse. Prototype Omnitrix only. Requires tier 2 and one Spore Capsule (ch.19/lv.40), one Void Alloy (ch.20/lv.41) and one Galactic Core (ch.21/lv.50). Each material has a 50% chance per completed victory, participant and race; previews grant no materials.','Nível 3 mantém as fusões anteriores e adiciona Quatro Insectóide por 200 s, com reutilização de 100 s. Apenas Omnitrix protótipo. Exige nível 2 e uma Cápsula de esporos (cap.19/nv.40), uma Liga do Vácuo (cap.20/nv.41) e um Núcleo galáctico (cap.21/nv.50). Cada material tem 50% por vitória completa, participante e raça; prévias não dão materiais.','Seviye 3 önceki füzyonları korur ve 200 sn Dört Kokarca ekler; yeniden kullanım 100 sn. Yalnız prototip Omnitrix. Seviye 2 ve bir Spor Kapsülü (böl.19/sv.40), bir Boşluk Alaşımı (böl.20/sv.41), bir Galaktik Çekirdek (böl.21/sv.50) gerekir. Her malzeme tam zaferde oyuncu ve ırk başına %50; önizleme malzeme vermez.');};
const partsBefore125=partsHTML121;partsHTML121=function(){const s=local121();return '<div data-no-i18n><h3>'+words97('Destornillador','Screwdriver','Chave de fenda','Tornavida')+' · '+s.tier+'/3</h3>'+Object.entries(PART_NAMES121).map(([k,n])=>'<p>'+words97(...n)+' · '+s.parts[k]+'/1</p>').join('')+'</div>';};
const appendBefore125=appendUpgrade121;appendUpgrade121=function(){appendBefore125();const s=local121();if(s.tier>=2){const old=$('#dialogbuttons').firstElementChild;old.disabled=true;old.textContent=words97('NIVEL 2 OBTENIDO','TIER 2 OBTAINED','NÍVEL 2 OBTIDO','SEVİYE 2 ALINDI');}const b=document.createElement('button');b.setAttribute('data-no-i18n','');b.textContent=s.tier===3?words97('NIVEL 3 OBTENIDO','TIER 3 OBTAINED','NÍVEL 3 OBTIDO','SEVİYE 3 ALINDI'):words97('MEJORAR A NIVEL 3 · 1 DE CADA MATERIAL NUEVO','UPGRADE TO TIER 3 · 1 OF EACH NEW MATERIAL','MELHORAR AO NÍVEL 3 · 1 DE CADA MATERIAL NOVO','SEVİYE 3 YÜKSELT · HER YENİ MALZEMEDEN 1');b.disabled=s.tier!==2||!tool107().owned||!NEW_PARTS125.every(k=>s.parts[k]>=1)||!pakmarVisible105()||dist(player,pakmar105)>150;b.onclick=()=>{if(upgradeTool125())pakmarTalk105();};$('#dialogbuttons').prepend(b);};
function fusionGuide125(){showDialog(words97('GUÍA · FUSIONES','GUIDE · FUSIONS','GUIA · FUSÕES','REHBER · FÜZYONLAR'),words97('Pakmar y los materiales','Pakmar and Materials','Pakmar e materiais','Pakmar ve Malzemeler'),'<div data-no-i18n><p>'+toolDescription107()+'</p>'+partsHTML121()+'</div>',[[words97('CAPÍTULOS · TEMPORADA 2','CHAPTERS · SEASON 2','CAPÍTULOS · TEMPORADA 2','BÖLÜMLER · SEZON 2'),seasonMenu121],[words97('VER TRANSFORMACIÓN','PREVIEW TRANSFORMATION','VER TRANSFORMAÇÃO','DÖNÜŞÜMÜ İZLE'),()=>movie125('bug125',0,'preview')],[words97('VOLVER','BACK','VOLTAR','GERİ'),()=>guide()]]);}
const guideBefore125=guide;guide=function(...a){guideBefore125(...a);const b=document.createElement('button');b.setAttribute('data-no-i18n','');b.textContent=words97('DESTORNILLADOR · DROPS Y FUSIONES','SCREWDRIVER · DROPS AND FUSIONS','CHAVE DE FENDA · DROPS E FUSÕES','TORNAVİDA · GANİMET VE FÜZYON');b.onclick=fusionGuide125;$('#dialogbuttons').prepend(b);};
