function shadowPalette156(image){const d=image.data,w=image.width,h=image.height,n=d.length/4,luma=new Uint8Array(n),warm=new Uint8Array(n);for(let p=0;p<n;p++){luma[p]=Math.round(d[p*4]*.2126+d[p*4+1]*.7152+d[p*4+2]*.0722);warm[p]=d[p*4]>70&&d[p*4]>d[p*4+1]*1.45&&d[p*4]>d[p*4+2]*1.2?1:0;}const histogram=new Uint32Array(256);let total=0;for(let p=0;p<n;p++)if(d[p*4+3]>100){histogram[luma[p]]++;total++;}let count=0,peak=255;for(let l=0;l<256;l++){count+=histogram[l];if(count>=total*.95){peak=Math.max(1,l);break;}}const gain=Math.min(3.2,Math.max(1,200/peak));for(let p=0;p<n;p++)luma[p]=Math.min(255,Math.round(luma[p]*gain));for(let p=0;p<n;p++){const i=p*4;if(!d[i+3])continue;const l=luma[p],x=p%w,y=Math.floor(p/w);let edge=0;if(x>0&&d[i-1]>100)edge=Math.max(edge,Math.abs(l-luma[p-1]));if(x<w-1&&d[i+7]>100)edge=Math.max(edge,Math.abs(l-luma[p+1]));if(y>0&&d[i-w*4+3]>100)edge=Math.max(edge,Math.abs(l-luma[p-w]));if(y<h-1&&d[i+w*4+3]>100)edge=Math.max(edge,Math.abs(l-luma[p+w]));let r,g,b;if(l<30){r=2+Math.round(l*.1);g=5+Math.round(l*.14);b=13+Math.round(l*.3);}else if(l<145){const t=(l-30)/115;r=5+Math.round(t*14);g=10+Math.round(t*43);b=25+Math.round(t*65);}else{const t=(l-145)/110;r=19+Math.round(t*14);g=53+Math.round(t*35);b=90+Math.round(t*43);if(edge>24){const glow=Math.min(1,(edge-24)/65+.2);r=Math.round(r*(1-glow)+(105+t*55)*glow);g=Math.round(g*(1-glow)+(215+t*30)*glow);b=Math.round(b*(1-glow)+(242+t*13)*glow);}}if(warm[p]){let count=0;for(let yy=Math.max(0,y-1);yy<=Math.min(h-1,y+1);yy++)for(let xx=Math.max(0,x-1);xx<=Math.min(w-1,x+1);xx++)count+=warm[yy*w+xx];if(count<=5){r=125;g=235;b=255;}}d[i]=r;d[i+1]=g;d[i+2]=b;}return image;}
