function saiPowerGap169(attacker,defender){const safe=v=>Number.isFinite(v)&&v>0?v:10;return clamp(Math.sqrt(safe(attacker)/safe(defender)),.35,10);}
function raditzDamage169(base){return damage248(saiHP167(),RADITZ_POWER168,effectivePower172(),base/300);}
function saiRegenRate169(){return 1.5+.16*Math.sqrt(Math.max(0,saiState167().power-10));}
