function kaiTalk172(){const o=otherState172();if(!otherHere172()||otherMap172()!==3)return false;if(o.stage===0)o.stage=1;let text,buttons=[];if(o.stage===1){text=L148('Antes de entrenarte, ¡hazme reír con un chiste!','Before I train you, make me laugh with a joke!','Antes do treino, faça-me rir com uma piada!','Eğitimden önce bir şakayla beni güldür!');buttons.push([L148('CONTAR UN CHISTE','TELL A JOKE','CONTAR PIADA','ŞAKA YAP'),kaiJoke172]);}else if(o.stage===2)text=L148('¡Atrapa a Bubbles! La gravedad es diez veces la de la Tierra. Corre; tu adaptación aumenta durante la persecución.','Catch Bubbles! Gravity is ten times Earth’s. Run; your adaptation grows during the chase.','Pegue Bubbles! A gravidade é dez vezes a da Terra. Corra; sua adaptação cresce na perseguição.','Bubbles’ı yakala! Yer çekimi Dünya’nın on katı. Koş; kovalarken uyumun artar.');else if(o.stage===3){text=L148('¡Lo atrapaste! Ya puedes aprender Kaioken y Genkidama. El entrenamiento inicial también te da +1.000 Power Level base, una sola vez.','You caught him! You can now learn Kaioken and Spirit Bomb. Initial training also grants +1,000 base Power Level once.','Você pegou! Agora pode aprender Kaioken e Genkidama. O treino inicial também dá +1.000 Power Level base uma vez.','Yakaladın! Kaioken ve Ruh Bombası öğrenebilirsin. İlk eğitim bir kez +1.000 temel Power Level verir.');buttons.push([L148('APRENDER TÉCNICAS','LEARN TECHNIQUES','APRENDER TÉCNICAS','TEKNİKLERİ ÖĞREN'),kaiTeach172]);}else{text=L148('Domina Kaioken mientras lo usas activamente. La maestría abre x2 al aprender, x4 a los270s, x10 a los900s y x20 a los1710s de práctica activa. Moverte, cargar ki o golpear cuenta; quedarse quieto no. Los multiplicadores altos agotan el ki y exigen descanso. La Genkidama reúne energía con los brazos arriba y se lanza por separado.','Master Kaioken through active use. Mastery unlocks x2 on learning, x4 at270s, x10 at900s and x20 at1710s of active practice. Moving, charging ki or attacking counts; idling does not. High multipliers drain ki and require rest. Spirit Bomb gathers energy with raised arms, then is thrown separately.','Domine Kaioken usando-o ativamente. A maestria abre x2 ao aprender, x4 em270s, x10 em900s e x20 em1710s de prática ativa. Mover, carregar ki ou atacar conta; ficar parado não. Multiplicadores altos drenam ki e exigem descanso. Genkidama reúne energia de braços erguidos e é lançada separadamente.','Kaioken’i aktif kullanarak geliştir. Aktif çalışma ile x2 öğrenince, x4 270sn, x10 900sn, x20 1710sn sonra açılır. Hareket, ki doldurma veya saldırı sayılır; beklemek sayılmaz. Yüksek çarpanlar ki tüketir ve dinlenme gerektirir. Ruh Bombası kollar yukarıda enerji toplar, sonra ayrıca atılır.');buttons.push(['KAIOKEN',kaiMenu172]);}text+='<br><br>'+L148('Dos saiyajins se aproximan. Te avisaré cuando llegue el año previsto; regresa a la Tierra y abre SAGA SAIYAN en el menú.','Two Saiyans are approaching. I will warn you in the expected year; return to Earth and open SAIYAN SAGA in the menu.','Dois saiyajins se aproximam. Avisarei no ano previsto; volte à Terra e abra SAGA SAIYAN no menu.','İki Saiyan yaklaşıyor. Beklenen yılda haber vereceğim; Dünya’ya dön ve menüden SAIYAN DESTANI aç.');buttons.push([L148('CONTINUAR','CONTINUE','CONTINUAR','DEVAM'),closeDialog]);persistGame();showDialog('NORTH KAI','KAIO-SAMA','<div data-no-i18n><p>'+text+'</p></div>',buttons);return true;}
function kaiMenu172(){const o=otherState172(),max=kaiMax172(),r=otherRun172;if(!sai167())return;const buttons=[[L148('DESACTIVAR','TURN OFF','DESATIVAR','KAPAT'),()=>kaiSet172(0)]];for(const i of [2,4,10,20].filter(v=>v<=max))buttons.push(['KAIOKEN x'+i,()=>kaiSet172(i)]);buttons.push([L148('VOLVER','BACK','VOLTAR','GERİ'),()=>saiMenu167('tech')]);showDialog('KAIOKEN',L148('Maestría','Mastery','Maestria','Ustalık')+' '+Math.floor(o.mastery)+' / 1710 s','<div data-no-i18n><p>'+L148('Base','Base','Base','Temel')+' '+saiNumber172(saiState167().power)+' → '+L148('Efectivo','Effective','Efetivo','Etkin')+' '+saiNumber172(effectivePower172())+'</p><p>'+L148('Solo multiplica daño y Power Level efectivo; no vida ni regeneración. Modos: x2, x4, x10 y x20.','Only multiplies damage and effective Power Level; not health or regeneration. Modes: x2, x4, x10 and x20.','Multiplica apenas dano e Power Level efetivo; não vida ou regeneração. Modos: x2, x4, x10 e x20.','Yalnızca hasarı ve etkin Power Level değerini çarpar; canı veya yenilenmeyi artırmaz. Kipler: x2, x4, x10 ve x20.')+'</p><p>'+L148('Consumo','Drain','Consumo','Tüketim')+': 2 + 0.6 × x KI/s · '+L148('Límite de esfuerzo','Strain limit','Limite de esforço','Zorlanma sınırı')+': 80 / x s · '+L148('Descanso','Rest','Descanso','Dinlenme')+': 8 s</p><p>'+L148('Descanso restante','Rest remaining','Descanso restante','Kalan dinlenme')+': '+Math.ceil(r.rest)+'s</p></div>',buttons);}
