function sagaEnemyUpdate173(e,dt){if(e.hp<=0)return;e.cd=Math.max(0,e.cd-dt);e.act=Math.max(0,e.act-dt);e.flash=Math.max(0,(e.flash||0)-dt);e.frame+=dt*10;e.moving=false;if(e.wind>0){e.wind=Math.max(0,e.wind-dt);if(e.wind===0){e.act=.7;const dx=e.aim.x-e.x,dy=e.aim.y-e.y,ang=Math.atan2(dy,dx);if(e.next==='melee'){if(dist(e,player)<(e.type==='ape'?330:175))sagaHurt173(e);}else if(e.next==='eruption'){sagaRun173.fx.push({kind:'eruption',x:e.aim.x,y:e.aim.y,t:.6,max:.6,color:'#ffcd63'});if(Math.hypot(player.x-e.aim.x,player.y-e.aim.y)<175)sagaHurt173(e,1.2);}else if(e.next==='beam'){sagaRun173.fx.push({kind:'beam',x:e.x,y:e.y-(e.type==='ape'?130:55),tx:e.x+Math.cos(ang)*1300,ty:e.y+Math.sin(ang)*1300-55,t:.65,max:.65,color:e.type==='ape'?'#ffdd85':'#cb8cff'});const f=(player.x-e.x)*Math.cos(ang)+(player.y-e.y)*Math.sin(ang),ac=Math.abs((player.x-e.x)*Math.sin(ang)-(player.y-e.y)*Math.cos(ang));if(f>=0&&f<1300&&ac<(e.type==='ape'?105:65))sagaHurt173(e,1.3);}else for(const spread of e.type==='saiba'?[0]:[-.18,0,.18])sagaRun173.shots.push({x:e.x,y:e.y-55,dx:Math.cos(ang+spread)*300,dy:Math.sin(ang+spread)*300,t:3,source:e,color:e.type==='saiba'?'#b3fb55':'#b686ff'});e.cd=e.type==='ape'?3.8:e.type==='saiba'?2.7:2.5;}}else if(e.cd===0){e.next=e.type==='saiba'?(e.hits%3===2?'ki':'melee'):e.type==='nappa'?(e.hits%3===0?'melee':e.hits%3===1?'eruption':'ki'):e.hits%3===1?'beam':'melee';e.wind=e.next==='melee'?.85:1.25;e.aim={x:player.x,y:player.y};e.hits++;}else if(dist(e,player)>(e.type==='ape'?230:145)&&e.act===0){const dx=player.x-e.x,dy=player.y-e.y,l=Math.hypot(dx,dy)||1,sp=e.type==='ape'?85:e.type==='saiba'?125:145;e.x=clamp(e.x+dx/l*sp*dt,180,1420);e.y=clamp(e.y+dy/l*sp*.7*dt,520,920);e.moving=true;}}
function sagaEvent173(key){const s=sagaState173();if(s.pending)return false;s.pending=key;s.panel=0;sagaSnapshot173();persistGame();sagaCinema173(key,0,false);return true;}
function sagaUpdate173(dt){const s=sagaState173(),r=sagaRun173;r.hurt=Math.max(0,r.hurt-dt);if(s.pending)return sagaCinema173(s.pending,s.panel,false);if(s.claims[s.phase-1])return;if(!r.fighters.length){sagaSeed173();sagaAlliesSeed173();}if(!sagaAllies173.length)sagaAlliesSeed173();for(const e of r.fighters){sagaEnemyUpdate173(e,dt);if(!sagaHere173())return;}sagaAllyUpdate173(dt);for(const sh of r.shots){sh.x+=sh.dx*dt;sh.y+=sh.dy*dt;sh.t-=dt;if(sh.t>0&&Math.hypot(sh.x-player.x,sh.y-(player.y-45))<35){sh.t=0;sagaHurt173(sh.source,.85);if(!sagaHere173())return;}}r.shots=r.shots.filter(x=>x.t>0);for(const f of r.fx)f.t-=dt;r.fx=r.fx.filter(f=>f.t>0);const dead=r.fighters.filter(e=>e.hp<=0).length;if(s.phase===1&&!s.yamcha&&dead>=1)return sagaEvent173('yamcha');if(s.phase===2&&!s.piccolo&&r.fighters[0]?.hp<=r.fighters[0]?.max*.55)return sagaEvent173('piccolo');if(s.phase===3&&s.form===0&&r.fighters[0]?.hp<=r.fighters[0]?.max*.5)return sagaEvent173('ape');if(s.phase===3&&s.form===1){s.apeTime+=dt;if(s.apeTime>=35)return sagaEvent173('tail');}if(r.fighters.length&&r.fighters.every(e=>e.hp<=0))return sagaReward173();r.save+=dt;if(r.save>=4){r.save=0;sagaSnapshot173();persistGame();}if(player.moving&&sagaRouteDelay175<=0&&player.dx<-.2&&Math.hypot(player.x-150,player.y-850)<85)return sagaExit175();}

const sagaScenes173={
arrival:{art:[0,0],lines:[['Vegeta y Nappa aterrizan para buscar las Esferas del Dragón. Los guerreros de la Tierra salen a su encuentro.','Vegeta and Nappa land in search of the Dragon Balls. Earth’s warriors gather to face them.','Vegeta e Nappa chegam em busca das Esferas do Dragão. Os guerreiros da Terra vão enfrentá-los.','Vegeta ve Nappa Ejder Topları için gelir. Dünya’nın savaşçıları karşılarına çıkar.'],['Nappa planta seis semillas: nacen los Saibamen. Tenshinhan demuestra que pueden ser vencidos. En esta adaptación juegas como Goku desde el primer combate junto a sus aliados.','Nappa plants six seeds: Saibamen emerge. Tien proves they can be beaten. In this adaptation you play as Goku alongside his allies from the first fight.','Nappa planta seis sementes: nascem os Saibamen. Tenshinhan prova que podem ser vencidos. Nesta adaptação você joga como Goku com os aliados desde a primeira luta.','Nappa altı tohum eker: Saibamanlar çıkar. Tenshinhan yenilebileceklerini gösterir. Bu uyarlamada ilk dövüşten itibaren müttefiklerle Goku’yu oynarsın.']]},
yamcha:{art:[1,2],lines:[['Yamcha cree haber vencido. El Saibaman se levanta, salta y se aferra a él. ¡Está reuniendo energía!','Yamcha believes he has won. The Saibaman gets up, leaps and clings to him. It is gathering energy!','Yamcha acredita que venceu. O Saibaman se levanta, salta e se agarra a ele. Está reunindo energia!','Yamcha kazandığını sanır. Saibaman kalkar, atlar ve ona sarılır. Enerji topluyor!'],['El Saibaman se autodestruye. Cuando se disipa el polvo, Yamcha yace en el cráter. Krillin y los demás deben continuar la batalla.','The Saibaman self-destructs. As the dust settles, Yamcha lies in the crater. Krillin and the others must continue the battle.','O Saibaman se autodestrói. A poeira baixa e Yamcha está caído na cratera. Krillin e os outros precisam continuar.','Saibaman kendini patlatır. Toz dağılınca Yamcha kraterde yatmaktadır. Krillin ve diğerleri savaşa devam etmelidir.']]},
nappa:{art:[0],lines:[['Los Saibamen han caído. Nappa entra en combate: su fuerza es muy superior. Gohan, Piccolo, Krillin y Tenshinhan luchan a tu lado. Observa sus avisos de ki y sal de las zonas marcadas.','The Saibamen are down. Nappa enters battle with far greater strength. Gohan, Piccolo, Krillin and Tien fight beside you. Watch his ki warnings and leave the marked areas.','Os Saibamen caíram. Nappa entra na luta com força muito maior. Gohan, Piccolo, Krillin e Tenshinhan lutam ao seu lado. Observe os avisos e saia das áreas marcadas.','Saibamanlar yenildi. Nappa çok daha büyük güçle dövüşe girer. Gohan, Piccolo, Krillin ve Tenshinhan yanında savaşır. Ki uyarılarını izle ve işaretli alanlardan çık.']]},
piccolo:{art:[3,3],lines:[['Tenshinhan lanza un último Kikoho contra Nappa, agotando sus fuerzas. Gohan intenta responder con un Masenko, pero el saiyajin prepara un golpe devastador.','Tien unleashes one final Tri-Beam against Nappa, exhausting his strength. Gohan tries to answer with Masenko, but the Saiyan prepares a devastating attack.','Tenshinhan lança um último Kikoho contra Nappa, esgotando suas forças. Gohan tenta responder com Masenko, mas o saiyajin prepara um golpe devastador.','Tenshinhan son Kikoho’sunu Nappa’ya atıp gücünü tüketir. Gohan Masenko ile karşılık verir; Saiyan yıkıcı bir saldırı hazırlar.'],['Piccolo se interpone para proteger a Gohan y recibe el ataque. Su sacrificio deja a Gohan y Krillin para ayudarte. En la historia original, Goku llega después de este momento.','Piccolo steps in to protect Gohan and takes the attack. His sacrifice leaves Gohan and Krillin to help you. In the original story, Goku arrives after this moment.','Piccolo se coloca na frente de Gohan e recebe o ataque. Seu sacrifício deixa Gohan e Krillin para ajudar você. Na história original, Goku chega depois desse momento.','Piccolo Gohan’ı korumak için araya girip saldırıyı karşılar. Fedakârlığından sonra Gohan ve Krillin sana yardım eder. Asıl hikâyede Goku bu andan sonra gelir.']]},
vegeta:{art:[0,0],lines:[['Goku supera a Nappa. Vegeta elimina cruelmente a su compañero y decide pelear por sí mismo. El príncipe saiyajin y Goku se alejan para su duelo.','Goku overcomes Nappa. Vegeta cruelly finishes his companion and decides to fight himself. The Saiyan prince and Goku move away for their duel.','Goku supera Nappa. Vegeta elimina cruelmente o companheiro e decide lutar. O príncipe saiyajin e Goku se afastam para o duelo.','Goku Nappa’yı yener. Vegeta acımasızca yoldaşının işini bitirip dövüşmeye karar verir. Saiyan prensi ve Goku düello için uzaklaşır.'],['Vegeta concentra su Galick Gun. Goku responde con el Kamehameha y fuerza su Kaioken. En el juego puedes entrenar x2, x4, x10 y x20; el poder base y la maestría siguen separados.','Vegeta charges his Galick Gun. Goku answers with Kamehameha and pushes Kaioken. In this game you can train x2, x4, x10 and x20; base power and mastery remain separate.','Vegeta concentra o Galick Gun. Goku responde com Kamehameha e força o Kaioken. No jogo você pode treinar x2, x4, x10 e x20; poder base e maestria continuam separados.','Vegeta Galick Gun toplar. Goku Kamehameha ile cevap verip Kaioken’i zorlar. Oyunda x2, x4, x10 ve x20 çalışabilirsin; temel güç ve ustalık ayrıdır.']]},
ape:{art:[4,4],lines:[['Vegeta lanza una Power Ball al cielo. La mezcla con la atmósfera para crear una luna llena artificial. Su cola responde a la luz.','Vegeta throws a Power Ball into the sky. Mixing with the atmosphere, it creates an artificial full moon. His tail responds to its light.','Vegeta lança uma Power Ball ao céu. Misturada à atmosfera, ela cria uma lua cheia artificial. Sua cauda reage à luz.','Vegeta gökyüzüne Power Ball atar. Atmosferle karışıp yapay dolunay oluşturur. Kuyruğu ışığa tepki verir.'],['Vegeta se transforma en Ōzaru: diez veces su Power Level. Esquiva sus puños y su rayo de boca. Resiste 35 segundos: Yajirobe buscará una oportunidad para cortar la cola.','Vegeta transforms into a Great Ape: ten times his Power Level. Dodge his fists and mouth beam. Survive for35 seconds while Yajirobe looks for an opening to cut his tail.','Vegeta vira Ōzaru: dez vezes seu Power Level. Desvie dos punhos e do raio da boca. Resista35 segundos enquanto Yajirobe procura uma chance de cortar a cauda.','Vegeta Ōzaru olur: Power Level on katına çıkar. Yumruklarını ve ağız ışınını atlat. Yajirobe kuyruğu kesme fırsatı ararken35 saniye dayan.']]},
tail:{art:[5,5],lines:[['Yajirobe espera hasta que Vegeta se distrae. Salta desde las rocas, desenvaina la espada y corta la cola con un solo movimiento.','Yajirobe waits until Vegeta is distracted. He leaps from the rocks, draws his sword and cuts the tail with one swing.','Yajirobe espera Vegeta se distrair. Salta das rochas, desembainha a espada e corta a cauda com um golpe.','Yajirobe Vegeta’nın dikkatinin dağılmasını bekler. Kayalardan atlayıp kılıcını çeker ve kuyruğu tek hamlede keser.'],['Sin cola, Vegeta vuelve a su forma base, herido. Gohan y Krillin regresan para ayudar a Goku. Termina el combate contra el príncipe debilitado.','Without his tail, Vegeta returns to his base form, wounded. Gohan and Krillin return to help Goku. Finish the fight against the weakened prince.','Sem a cauda, Vegeta volta ferido à forma base. Gohan e Krillin retornam para ajudar Goku. Termine a luta contra o príncipe enfraquecido.','Kuyruksuz Vegeta yaralı temel biçimine döner. Gohan ve Krillin Goku’ya yardıma gelir. Zayıflayan prensle dövüşü bitir.']]},
ending:{art:[0,0],lines:[['Gohan y Krillin ayudan a Goku a resistir; la Genkidama es decisiva en el enfrentamiento. En el relato original, Gohan también se transforma en Ōzaru y acaba cayendo sobre Vegeta.','Gohan and Krillin help Goku endure; the Spirit Bomb plays a decisive role. In the original story, Gohan also becomes a Great Ape and ultimately falls onto Vegeta.','Gohan e Krillin ajudam Goku a resistir; a Genkidama é decisiva. No relato original, Gohan também vira Ōzaru e acaba caindo sobre Vegeta.','Gohan ve Krillin Goku’nun dayanmasına yardım eder; Ruh Bombası belirleyici olur. Asıl hikâyede Gohan da Ōzaru olup Vegeta’nın üstüne düşer.'],['Krillin quiere acabar con Vegeta, pero Goku pide dejarlo marchar. Vegeta escapa en su cápsula. La saga termina; puedes repetir las tres fases o volver a ver las cinemáticas.','Krillin wants to finish Vegeta, but Goku asks him to let him go. Vegeta escapes in his pod. The saga ends; you can replay all three phases or rewatch the cinematics.','Krillin quer acabar com Vegeta, mas Goku pede que o deixe partir. Vegeta foge na cápsula. A saga termina; você pode repetir as três fases ou rever as cenas.','Krillin Vegeta’nın işini bitirmek ister, ama Goku gitmesine izin vermesini ister. Vegeta kapsülle kaçar. Destan biter; üç aşamayı tekrar oynayabilir veya sahneleri izleyebilirsin.']]}
};
function sagaCinemaFinish173(){const c=sagaRun173.cinema;if(!c)return false;sagaRun173.cinema=null;sagaRun173.token++;if(c.preview){closeDialog();sagaMenu173();return true;}const s=sagaState173();if(s.pending!==c.key)return false;s.pending='';s.panel=0;if(c.key==='yamcha'&&!s.yamcha){s.yamcha=true;const e=sagaRun173.fighters.find(e=>e.hp>0);if(e)e.hp=0;}if(c.key==='piccolo')s.piccolo=true;if(c.key==='ape'){s.form=1;s.apeTime=0;s.saved=[];sagaRun173.fighters=[sagaMake173(0,'ape',1100,740)];}if(c.key==='tail'){s.form=2;s.saved=[];const e=sagaMake173(0,'vegeta',1100,740);e.max=e.hp=3500;sagaRun173.fighters=[e];}sagaRun173.shots=[];sagaRun173.fx=[];if(c.key==='ape'||c.key==='tail'){saiRun167.action=saiRun167.beam=null;saiRun167.shot=[];otherRun172.genki=otherRun172.bomb=null;otherRun172.kai=0;otherRun172.rest=Math.max(8,otherRun172.rest);otherRun172.strain=0;}sagaAlliesSeed173();sagaSnapshot173();closeDialog();persistGame();if(c.key==='ending')sagaMenu173();return true;}
function sagaCinema173(key,panel=0,preview=false){if(!sai167()||!sagaScenes173[key])return false;const spec=sagaScenes173[key];panel=clamp(Math.floor(panel),0,spec.lines.length-1);const token=++sagaRun173.token;sagaRun173.cinema={key,panel,preview};if(!preview){const s=sagaState173();if(s.pending!==key)return false;s.panel=panel;persistGame();}const next=()=>panel+1<spec.lines.length?sagaCinema173(key,panel+1,preview):sagaCinemaFinish173();showDialog('DRAGON BALL Z · '+L148('SAGA SAIYAN','SAIYAN SAGA','SAGA SAIYAN','SAIYAN DESTANI'),L148('Historia','Story','História','Hikâye')+' · '+(panel+1)+' / '+spec.lines.length,'<div data-no-i18n><canvas id="saga-cinema173" class="raditz-scene168" width="768" height="432"></canvas><p>'+L148(...spec.lines[panel])+'</p></div>',[[L148('SIGUIENTE','NEXT','PRÓXIMO','SONRAKİ'),next],[L148('SALTAR CINEMÁTICA','SKIP CINEMATIC','PULAR CINEMÁTICA','SİNEMATİĞİ ATLA'),sagaCinemaFinish173]]);const start=performance.now(),paint=()=>{if(token!==sagaRun173.token||!sagaRun173.cinema)return;const el=document.getElementById('saga-cinema173');if(!el)return;const cc=el.getContext('2d'),im=sagaArt173.cinema,t=(performance.now()-start)/1000,index=spec.art[panel],sw=im.width/2,sy=[0,317,649][Math.floor(index/2)],sh=[317,332,375][Math.floor(index/2)];cc.imageSmoothingEnabled=false;if(im.complete&&im.naturalWidth){const z=1+.015*Math.sin(t*.65),w=768*z,h=432*z;cc.drawImage(im,index%2*sw,sy,sw,sh,(768-w)/2,(432-h)/2,w,h);}if(key==='arrival'&&panel===1){for(let i=0;i<6;i++)sagaPaint173('enemies',2,Math.floor(t*6)%4,180+i*83,380,75,i>2,cc);}if(key==='yamcha'&&panel===0){cc.save();cc.globalCompositeOperation='screen';cc.fillStyle='rgba(255,245,150,'+(.08+.16*Math.abs(Math.sin(t*4)))+')';cc.beginPath();cc.arc(500,260,65+Math.sin(t*5)*15,0,Math.PI*2);cc.fill();cc.restore();}if(key==='yamcha'&&panel===1){cc.fillStyle='rgba(255,240,180,'+Math.max(0,.8-t*.4)+')';cc.fillRect(0,0,768,432);for(let i=0;i<12;i++){cc.fillStyle='#d9b58544';cc.fillRect((i*79+t*22)%768,70+i*24,60,6);}}if(key==='vegeta'&&panel===1){cc.strokeStyle='#be76ff99';cc.lineWidth=30;cc.beginPath();cc.moveTo(650,230);cc.lineTo(390+Math.sin(t*4)*20,260);cc.stroke();cc.strokeStyle='#b4f7ff';cc.lineWidth=22;cc.beginPath();cc.moveTo(120,280);cc.lineTo(390+Math.sin(t*4)*20,260);cc.stroke();}if(key==='ape'){cc.strokeStyle='#fffdccbb';cc.lineWidth=3;cc.beginPath();cc.arc(580,80,32+Math.sin(t*4)*5,0,Math.PI*2);cc.stroke();}if(key==='tail'&&panel===0){cc.strokeStyle='#fff8ba';cc.lineWidth=6;cc.beginPath();cc.moveTo(550+Math.sin(t*4)*20,130);cc.lineTo(350,350);cc.stroke();}if(key==='ending'&&panel===1){cc.fillStyle='#d9e2ed';cc.beginPath();cc.ellipse(650,310-Math.min(220,t*30),35,43,0,0,Math.PI*2);cc.fill();}requestAnimationFrame(paint);};paint();return true;}

function sagaMenu173(){if(!sai167())return false;const s=sagaState173(),o=otherState172(),eligible=sagaEligible173();let body='<div data-no-i18n class="sai-dialog167"><p>'+L148('Tres fases: Saibamen → Nappa → Vegeta / Ōzaru. Cada fase da 600 Power Level la primera vez y 400 al repetirla. Ver o saltar escenas no entrega recompensas.','Three phases: Saibamen → Nappa → Vegeta / Great Ape. Each phase grants 600 Power Level the first time and 400 on replays. Watching or skipping scenes grants no rewards.','Três fases: Saibamen → Nappa → Vegeta / Ōzaru. Cada fase dá 600 Power Level na primeira vitória e 400 nas repetições. Ver ou pular cenas não dá recompensa.','Üç aşama: Saibamanlar → Nappa → Vegeta / Ōzaru. Her aşama ilk zaferde600Power Level,tekrarlarda400verir. Sahne izlemek veya atlamak ödül vermez.')+'</p><p>Saibamen 30.000 · Nappa 60.000 · Vegeta 150.000 · Ōzaru 1.500.000</p><p>'+L148('Aliados (valores del juego)','Allies (game balance values)','Aliados (valores do jogo)','Müttefikler (oyun denge değerleri)')+': Gohan35.000 · Piccolo45.000 · Krillin32.000 · Yamcha28.000 · Tenshinhan38.000</p><p>'+L148('Requisitos: vencer a Raditz, aprender con Kaio-sama, estar vivo y llegar al año previsto.','Requirements: defeat Raditz, learn from King Kai, be alive and reach the expected year.','Requisitos: vencer Raditz, aprender com Kaio, estar vivo e chegar ao ano previsto.','Gerekenler: Raditz’i yen, Kral Kai’den öğren, hayatta ol ve beklenen yıla ulaş.')+' '+L148('Año','Year','Ano','Yıl')+' '+saiYear172()+' / '+(o.arrivalYear||762)+'</p><p>'+L148('Fase','Phase','Fase','Aşama')+' '+s.phase+'/3 · '+L148('Sagas completadas','Completed sagas','Sagas concluídas','Tamamlanan destanlar')+' '+s.wins+'</p><p>'+L148('Adaptación jugable: Goku combate desde el inicio; las cinemáticas explican los acontecimientos originales.','Playable adaptation: Goku fights from the start; cinematics explain the original events.','Adaptação jogável: Goku luta desde o início; as cenas explicam os eventos originais.','Oynanabilir uyarlama: Goku baştan savaşır; sinematikler asıl olayları açıklar.')+'</p></div>';const buttons=[];if(eligible){if(!s.phase||s.complete)buttons.push([s.complete?L148('REPETIR SAGA','REPLAY SAGA','REPETIR SAGA','DESTANI TEKRARLA'):L148('COMENZAR SAGA','START SAGA','INICIAR SAGA','DESTANI BAŞLAT'),sagaStart173]);else if(sagaHere173()&&s.claims[s.phase-1])buttons.push([L148('SIGUIENTE FASE','NEXT PHASE','PRÓXIMA FASE','SONRAKİ AŞAMA'),sagaNext173]);else buttons.push([L148('CONTINUAR SAGA','CONTINUE SAGA','CONTINUAR SAGA','DESTANA DEVAM'),sagaEnter173]);}for(const [key,label]of [['arrival',['LLEGADA','ARRIVAL','CHEGADA','GELİŞ']],['yamcha',['YAMCHA','YAMCHA','YAMCHA','YAMCHA']],['nappa',['NAPPA','NAPPA','NAPPA','NAPPA']],['piccolo',['PICCOLO','PICCOLO','PICCOLO','PICCOLO']],['vegeta',['VEGETA','VEGETA','VEGETA','VEGETA']],['ape',['TRANSFORMACIÓN ŌZARU','GREAT APE TRANSFORMATION','TRANSFORMAÇÃO ŌZARU','ŌZARU DÖNÜŞÜMÜ']],['tail',['CORTE DE COLA','TAIL CUT','CORTE DA CAUDA','KUYRUK KESİMİ']],['ending',['FINAL','ENDING','FINAL','SON']]])buttons.push(['▶ '+L148(...label),()=>sagaCinema173(key,0,true)]);buttons.push([L148('CERRAR','CLOSE','FECHAR','KAPAT'),closeDialog]);showDialog('DRAGON BALL Z',L148('SAGA SAIYAN','SAIYAN SAGA','SAGA SAIYAN','SAIYAN DESTANI'),body,buttons);return true;}
