function utFlowerChoice210(){utSay210('flowerchoice',null,[[T210('spare'),()=>utResolveFlower210(false)],[T210('kill'),()=>utResolveFlower210(true)]]);}
function utResolveFlower210(kill){const n=utState207(),c=n.chapter210;c.floweyDead=!!kill;c.floweyChoice=true;utRun207.text210=null;utRun207.mode='world';persistGame();if(kill)utSay210('flowerdead');}
