function utRoomGate210(room,side){const c=utState207().chapter210,f=c.flags;if(side==='e'){if(room==='switches'&&(!f.switchA||!f.switchB))return'switches';if(room==='dummy'&&!f.dummy)return'dummy';if(room==='spikes'&&!f.escort)return'spikes';if(room==='pit'&&!f.pit)return'pit';if(room==='boulders'&&!f.boulders)return'boulder';if(room==='napstablook'&&!f.ghost)return'ghost';if(room==='colors'&&!f.colors)return'colors';if(room==='basement'&&c.toriel==='alive')return'leave';if(room==='exit'&&!c.floweyChoice)return'flowerchoice';}return null;}
function utTryDoor210(side,target){const r=utRun207,c=utState207().chapter210,locked=utRoomGate210(c.room,side);if(locked){if(locked==='leave')utAskLeave210();else utSay210(locked);return false;}const opposite={e:'w',w:'e',n:'s',s:'n',basement:'n'};utGo210(target,opposite[side]);return true;}
function utRoomBlocked210(x,y){const c=utState207().chapter210;if(x<62||x>898||y<204||y>435)return true;if(c.room==='spikes'&&!c.flags.escort){return x>180&&x<810;}if(c.room==='living'&&((x>260&&x<680&&y>265&&y<405)||(x>185&&x<320&&y<260)))return true;if(c.room==='bedroom'&&x>640&&x<840&&y<390)return true;return false;}
