function gearState226(){let q=player.gear226;if(!q||q.v!==1)q=player.gear226={v:1,items:{},plans:{},forms:{},active:{},salvage:{},emitterUntil:0,stabilizerUntil:0};if(cleanGear226.has(q))return q;for(const k of ['items','plans','forms','active','salvage'])if(!q[k]||typeof q[k]!=='object'||Array.isArray(q[k]))q[k]={};for(const k of ['resist','energy','practice','power','cool','effect'])q.items[k]=clamp(Math.floor(Number(q.items[k])||0),0,999999);const now=Date.now();for(const [k,b]of Object.entries(q.active))if(!['resist','practice'].includes(k)||!Number.isFinite(b)||b<=now||b>now+3600000)delete q.active[k];for(const k of ['emitterUntil','stabilizerUntil'])q[k]=clamp(Number(q[k])||0,0,now+30000);for(const [k,m]of Object.entries(q.forms))if(!formKeys226().includes(k)||!['power','cool','effect'].includes(m?.kind)||!Number.isInteger(m.i)||m.i<0||m.i>=formSkills226(k).length)delete q.forms[k];q.guardUntil=clamp(Number(q.guardUntil)||0,0,now+3000);cleanGear226.add(q);return q;}
function formKeys226(){if(!lootEligible226())return [];return race===SYSTEM148?[SYSTEM148+':base']:domainKeys214();}
function formKey226(){return !lootEligible226()?null:race===SYSTEM148?SYSTEM148+':base':race==='omni'&&!recal115()?null:domainKey214();}
function formSkills226(key){if(!key)return[];if(key.startsWith('bendy:'))return key.endsWith(':beast')?BEAST_SKILLS26:RACE_SKILLS26.bendy;if(key.startsWith(SYSTEM148+':'))return ALIENS[SYSTEM148]?.skills||[];return skills217(key);}
function formName226(k){if(k?.startsWith(SYSTEM148+':'))return L226('Sistema · Jinwoo','System · Jinwoo','Sistema · Jinwoo','Sistem · Jinwoo');return domainName214(k);}
function activeModule226(){const key=formKey226();return key?gearState226().forms[key]||null:null;}
const recipes226={resist:{plan:2,cost:{essence:2,nuts:4,scrap:6}},energy:{plan:2,cost:{essence:1,nuts:3,scrap:5}},practice:{plan:3,cost:{essence:3,nuts:6,scrap:8}},power:{plan:4,cost:{essence:6,nuts:12,scrap:18}},cool:{plan:4,cost:{essence:6,nuts:12,scrap:18}},effect:{plan:4,cost:{essence:6,nuts:12,scrap:18}}};
