raidArt225=itemArt226;
function costs226(cost){return Object.entries(cost).map(([k,n])=>n+' '+(raidNames225[k]?T225(k):L226(...materialDefs217[k][0]))).join(' · ');}
function spend226(cost,run){if(!lootEligible226()||!cost||Object.values(cost).some(n=>!Number.isSafeInteger(n)||n<0))return false;const r=raidState225(),m=materials217();if(Object.entries(cost).some(([k,n])=>(['sample','essence','blueprint'].includes(k)?r.items[k]:m[k]||0)<n))return false;for(const[k,n]of Object.entries(cost))if(['sample','essence','blueprint'].includes(k))r.items[k]-=n;else m[k]-=n;run();persistGame();return true;}
function research226(id){const q=gearState226(),d=recipes226[id];if(!d||q.plans[id])return false;return spend226({sample:d.plan},()=>q.plans[id]=true);}
function craft226(id){const q=gearState226(),d=recipes226[id];if(!d||!q.plans[id]||q.items[id]>=999999)return false;return spend226(d.cost,()=>q.items[id]++);}
function energyResource226(){if(race===SYSTEM148)return{o:player.system148,k:'mana',cap:manaMax148()};if(race==='anodite'||race==='bendy')return{o:player,k:'raceResource26',cap:race==='anodite'?manaCap205():100};return{o:player,k:'battery',cap:race==='omni'?omniCap53():100};}
function useCraft226(id){if(!lootEligible226())return false;const q=gearState226();if(!['resist','energy','practice'].includes(id)||q.items[id]<1||!started||cinematic||player.hp<=0||blocked112())return false;if(id==='energy'){const r=energyResource226();if(!r.o||!Number.isFinite(r.o[r.k])||r.o[r.k]>=r.cap)return false;r.o[r.k]=Math.min(r.cap,r.o[r.k]+r.cap*.2);}else{const now=Date.now();if((q.active[id]||0)>now)return false;q.active[id]=now+600000;}q.items[id]--;persistGame();hud();return true;}
function exchange226(kind){const q=raidState225();if(kind==='sample')return spend226({blueprint:2},()=>q.items.sample++);if(kind==='salvage')return spend226({blueprint:1},()=>{const m=materials217();m.nuts=Math.min(999999,m.nuts+5);m.scrap=Math.min(999999,m.scrap+3);});return false;}
const domainBefore226=domainGain214;domainGain214=function(key,n,...a){const q=lootEligible226()?gearState226():null,bonus=q?.active.practice>Date.now()&&boost219('mastery')===1?1.25:1;return domainBefore226(key,n*bonus,...a);};
const xpBefore226=xp;xp=function(n,...a){const q=lootEligible226()?gearState226():null,bonus=net.source!=='guest'&&q?.active.practice>Date.now()&&practiceKind226()==='xp'&&boost219('xp')===1?1.25:1;return xpBefore226(n*bonus,...a);};
function moduleSkill226(){return skillContext217??inferred217()??(race==='bendy'?player.raceCast26?.i??(player.raceDash26?2:null):race===SYSTEM148?player.system148?.animation?.i:null);}
const multiplierBefore226=multiplier;multiplier=function(...a){const m=activeModule226();return multiplierBefore226(...a)*(net.source!=='guest'&&m?.kind==='power'&&m.i===moduleSkill226()?1.05:1);};
const attackRunBefore226=runAttack217;runAttack217=function(i,fn){const key=formKey226(),m=key?gearState226().forms[key]:null,before=player.cool?.[i]||0,oldCast=player.attack,now=Date.now();const r=attackRunBefore226(i,fn),cast=r!==false&&((player.cool?.[i]||0)>before||(player.attack||0)>oldCast);if(cast&&m?.i===i){if(m.kind==='cool'&&player.cool?.[i]>before)player.cool[i]*=.95;if(m.kind==='effect'&&gearState226().stabilizerUntil<=now){gearState226().stabilizerUntil=now+10000;gearState226().guardUntil=now+3000;}}return r;};
const hurtBefore226=hitPlayer;hitPlayer=function(d,...a){return hurtBefore226(d*(lootEligible226()&&gearState226().guardUntil>Date.now()?.95:1),...a);};
function slowReduction226(){if(!lootEligible226())return 0;const q=raidState225();return Math.max(q.equipped==='boots'?.15+(q.devices.boots||0)*.15:0,gearState226().active.resist>Date.now()?.25:0);}
const statusUpdateBefore226=updateStatus;updateStatus=function(o,dt){const before=o?.slow||0,r=statusUpdateBefore226(o,dt);if(o===player&&before>0){const reduction=slowReduction226();if(reduction>0)o.slow=Math.max(0,before-dt/(1-reduction));}return r;};
function equipModule226(key,kind,i){const q=gearState226();if(!lootEligible226()||key!==formKey226()||!formKeys226().includes(key)||!['power','cool','effect'].includes(kind)||!Number.isInteger(i)||i<0||!formSkills226(key)[i]||!unlockedSkill(skillId(),i)||formSkills226(key)[i].cd<=0)return false;const old=q.forms[key];if(old?.kind===kind&&old.i===i)return false;if(old?.kind!==kind&&q.items[kind]<1)return false;if(old?.kind!==kind){q.items[kind]--;if(old)q.items[old.kind]++;}q.forms[key]={kind,i};persistGame();return true;}
function removeModule226(key){const q=gearState226(),m=q.forms[key];if(!lootEligible226()||!formKeys226().includes(key)||!m)return false;q.items[m.kind]++;delete q.forms[key];persistGame();return true;}
function moduleMenu226(key=formKey226()||formKeys226()[0]){if(!lootEligible226()||!key)return false;const q=gearState226(),m=q.forms[key],skills=formSkills226(key);showDialog('RAIDS · '+T226('mods'),formName226(key),'<section class="loot-panel226" data-no-i18n><div class="loot-nav226"><select id="module-form226" aria-label="'+T226('form')+'">'+formKeys226().map(k=>'<option value="'+k+'" '+(k===key?'selected':'')+'>'+esc217(formName226(k))+'</option>').join('')+'</select><b>'+ (m?T226(m.kind)+' · '+nameSkill217(skills[m.i],m.i):T226('unassigned'))+'</b></div><p>'+L226('Un módulo activo por forma. Equipar consume una unidad libre; quitarla la devuelve. Solo se puede equipar en la forma actual y en habilidades desbloqueadas.','One active module per form. Equipping uses a free unit; removing returns it. Equip only on the current form and unlocked abilities.','Um módulo ativo por forma. Equipar usa uma unidade livre; remover a devolve. Equipe apenas na forma atual e em habilidades desbloqueadas.','Biçim başına bir etkin modül. Takmak boş birim kullanır; çıkarmak geri verir. Yalnız mevcut biçim ve açık yeteneklerde takılır.')+'</p><div class="module-grid226">'+['power','cool','effect'].map(kind=>'<article>'+itemArt226(kind)+'<h3>'+T226(kind)+'</h3><p>'+description226(kind)+'</p><b>'+L226('Libres','Free','Livres','Boş')+': '+q.items[kind]+'</b><select data-module-skill226="'+kind+'" aria-label="'+T226('ability')+'">'+skills.map((s,i)=>s.cd>0?'<option value="'+i+'" '+(m?.i===i?'selected':'')+'>'+esc217(nameSkill217(s,i))+'</option>':'').join('')+'</select><button data-equip226="'+kind+'" '+(key!==formKey226()||q.items[kind]<1&&m?.kind!==kind?'disabled':'')+'>'+T226('equip')+'</button></article>').join('')+'</div><p>'+L226('La bonificación se suma como una mejora pequeña al progreso existente. No modifica ni regala niveles de dominio.','This is a small additional upgrade to existing progress. Does not change or grant mastery levels.','É uma pequena melhoria adicional ao progresso existente. Não altera nem concede níveis de domínio.','Mevcut ilerlemeye küçük ek geliştirmedir. Ustalık seviyesi değiştirmez veya vermez.')+'</p></section>',[[T226('remove'),()=>{removeModule226(key);moduleMenu226(key);}],[T226('workshop'),researchMenu225],[T226('close'),closeDialog]]);$('#module-form226').onchange=e=>moduleMenu226(e.target.value);for(const b of document.querySelectorAll('[data-equip226]'))b.onclick=()=>{const kind=b.dataset.equip226,i=Number(document.querySelector('[data-module-skill226="'+kind+'"]').value);if(!equipModule226(key,kind,i))toast(L226('Usa esta forma y desbloquea la habilidad primero. Necesitas un módulo libre.','Use this form and unlock the ability first. A free module is required.','Use esta forma e desbloqueie a habilidade primeiro. É necessário um módulo livre.','Önce bu biçimi kullan ve yeteneği aç. Boş modül gerekir.'));moduleMenu226(key);};dragPanel223($('#dialogbody'));return true;}
researchMenu225=function(){if(!lootEligible226())return false;const q=raidState225(),s=gearState226(),m=materials217();showDialog('RAIDS · MAX',T226('workshop'),'<section class="loot-panel226" data-no-i18n><header><b>'+T225('sample')+': '+q.items.sample+' · '+T225('essence')+': '+q.items.essence+' · '+T225('blueprint')+': '+q.items.blueprint+'</b><p>'+L226('Las recetas y los objetos se guardan por raza. Los dispositivos también funcionan en la aventura normal.','Recipes and items are saved per race. Devices also work in the normal adventure.','Receitas e objetos são salvos por raça. Dispositivos também funcionam na aventura normal.','Tarif ve eşyalar ırka göre kaydedilir. Cihazlar normal macerada da çalışır.')+'</p></header><nav class="loot-nav226"><button id="open-modules226">'+T226('mods')+'</button><button id="open-bag226">'+L226('MOCHILA','BACKPACK','MOCHILA','ÇANTA')+'</button></nav><h3>'+L226('DISPOSITIVOS DE EXPLORACIÓN','EXPLORATION DEVICES','DISPOSITIVOS DE EXPLORAÇÃO','KEŞİF CİHAZLARI')+'</h3><div class="module-grid226">'+Object.entries(raidDevice225).map(([id,d])=>{const level=q.devices[id]||0,plan=q.plans[id],cost=plan?{essence:d.cost.essence*(level+1),nuts:d.cost.nuts*(level+1),scrap:d.cost.scrap*(level+1)}:{sample:d.cost.sample};return '<article>'+itemArt226(id)+'<h3>'+T225(id)+' '+level+'/3</h3><p>'+deviceDescription225(id)+'</p><small>'+costs226(cost)+'</small><button data-device-craft226="'+id+'" '+(level>=3?'disabled':'')+'>'+(level>=3?L226('MÁXIMO','MAXIMUM','MÁXIMO','AZAMİ'):plan?T226('craft'):T226('research'))+'</button></article>';}).join('')+'</div><h3>'+L226('CONSUMIBLES Y MODIFICADORES','CONSUMABLES AND MODIFIERS','CONSUMÍVEIS E MODIFICADORES','TÜKETİLEBİLİRLER VE MODÜLLER')+'</h3><div class="module-grid226">'+Object.entries(recipes226).map(([id,d])=>'<article>'+itemArt226(id)+'<h3>'+T226(id)+'</h3><p>'+description226(id)+'</p><small>'+costs226(s.plans[id]?d.cost:{sample:d.plan})+'</small><button data-craft226="'+id+'">'+(s.plans[id]?T226('craft'):T226('research'))+'</button></article>').join('')+'</div><h3>'+T226('exchanges')+'</h3><div class="loot-nav226"><button data-exchange226="sample">2 '+T225('blueprint')+' → 1 '+T225('sample')+'</button><button data-exchange226="salvage">1 '+T225('blueprint')+' → 5 '+L226('tuercas','nuts','porcas','somun')+' + 3 '+L226('chatarra','scrap','sucata','hurda')+'</button></div><p>'+L226('Las recetas requieren materiales obtenidos jugando. No se compran niveles de dominio.','Recipes require materials earned by playing. Mastery levels cannot be purchased.','Receitas exigem materiais obtidos jogando. Níveis de domínio não podem ser comprados.','Tarifler oynayarak kazanılan malzeme gerektirir. Ustalık seviyesi satın alınmaz.')+'</p></section>',[[T226('back'),()=>raidMenu225()],[T226('close'),closeDialog]]);for(const b of document.querySelectorAll('[data-craft226]'))b.onclick=()=>{const id=b.dataset.craft226;if(!(s.plans[id]?craft226(id):research226(id)))toast(T226('materials'));researchMenu225();};for(const b of document.querySelectorAll('[data-device-craft226]'))b.onclick=()=>{if(!research225(b.dataset.deviceCraft226))toast(T226('materials'));researchMenu225();};for(const b of document.querySelectorAll('[data-exchange226]'))b.onclick=()=>{if(!exchange226(b.dataset.exchange226))toast(T226('materials'));researchMenu225();};$('#open-modules226').onclick=()=>moduleMenu226();$('#open-bag226').onclick=()=>bag217();dragPanel223($('#dialogbody'));return true;};
