function power248(v){return Number.isFinite(v)&&v>0?v:10;}
function ratio248(a,d){return clamp(power248(a)/power248(d),1e-24,1e24);}
function scale248(a,d){const r=ratio248(a,d);return Math.pow(r,r>=1?.85:1.35);}
function coreHP248(p){return 120+Math.sqrt(Math.max(0,power248(p)-10))*5;}
function damage248(max,a,d,strength=.08){if(!Number.isFinite(max)||max<=0||!Number.isFinite(strength)||strength<=0)return 0;if(ratio248(a,d)>=20)return max;return coreHP248(d)*strength*scale248(a,d);}
function playerDamage248(max,def,d){if(!Number.isFinite(d)||d<=0)return 0;return damage248(max,effectivePower172(),def,.08*d/Math.max(1e-12,saiDamage167(20)));}
