function open249(page='world',selected=0){if(!sai167()||!started)return false;open244('tech');run249.menu=page;run249.selection=selected;panel244.querySelector('.panel-head244 b').textContent=w249(page==='skills'?'mastery':page);const el=panel244.querySelector('#panel-body244');el.className='adventure-layout249';const tabs=['world','training','mastery','companion'];el.innerHTML='<nav class="frame244 tabs249">'+tabs.map(p=>'<button data-page249="'+p+'" class="'+(p===page?'active':'')+'">'+(p==='training'?T249('ENTRENAR','TRAIN','TREINAR','ANTRENMAN'):w249(p))+'</button>').join('')+'</nav><article class="frame244 list249"><h2></h2><div class="scroll244"></div></article><article class="frame244 detail244"><div class="info249"></div></article>';for(const b of el.querySelectorAll('[data-page249]'))b.onclick=()=>open249(b.dataset.page249);const list=el.querySelector('.scroll244'),info=el.querySelector('.info249'),title=el.querySelector('.list249 h2');const s=state249();if(page==='world'||page==='training'){title.textContent=w249(page);const defs=questDefs249.filter(d=>page==='world'?['city','valley','namek'].includes(d.place)||d.id==='defense'||d.id==='secret':d.place==='arena'),d=defs[clamp(selected,0,defs.length-1)];list.innerHTML=defs.map((d,i)=>'<button data-q249="'+i+'" class="tech-row244 '+(i===selected?'selected':'')+'">'+icon249(d.mode==='escort'?6:d.place==='arena'?5:7)+'<b>'+T249(...d.n)+'</b><span class="green244">'+(s.records[d.id]?'✓ '+s.records[d.id]:'')+'</span></button>').join('');for(const b of list.querySelectorAll('[data-q249]'))b.onclick=()=>open249(page,Number(b.dataset.q249));info.innerHTML=icon249(7)+'<h2>'+T249(...d.n)+'</h2><p>'+T249(...d.d)+'</p><p class="green244">+259 Power Level · +150 '+T249('zenis','zeni','zenis','zeni')+'</p><p>'+T249('Repetible. El progreso y el premio se guardan por perfil.','Repeatable. Progress and rewards are saved per profile.','Repetível. Progresso e prêmio salvos por perfil.','Tekrarlanabilir. İlerleme ve ödüller profile kaydedilir.')+'</p>'+(s.quest?'<p>'+T249('Encargo activo','Active request','Pedido ativo','Etkin iş')+': '+T249(...quest249(s.quest.id).n)+' · '+s.quest.step+'</p><button id="abandon249">'+w249('abandon')+'</button>':'<button id="accept249" '+(!eligible249(d)?'disabled':'')+'>'+w249('accept')+'</button>')+'<p>'+(!eligible249(d)?T249('Completa primero los requisitos de viaje, historia o aprendizaje de esta actividad.','Complete this activity’s travel, story or technique requirements first.','Conclua os requisitos de viagem, história ou técnica desta atividade.','Önce etkinliğin yolculuk, hikâye veya teknik şartlarını tamamla.'):'')+'</p>';const b=info.querySelector('#accept249');if(b)b.onclick=()=>startQuest249(d.id);const ab=info.querySelector('#abandon249');if(ab)ab.onclick=()=>{abandon249();open249(page,selected);};}
if(page==='mastery'||page==='skills'){title.textContent=w249('mastery');const ids=masterIDs249,k=ids[clamp(selected,0,ids.length-1)],rank=rank249(k),xp=s.xp[k];list.innerHTML=ids.map((id,i)=>'<button data-m249="'+i+'" class="tech-row244 '+(selected===i?'selected':'')+'">'+(actionDefs249.some(a=>a.id===id)?icon249(actionDefs249.find(a=>a.id===id).icon):icon244(techDefs244.find(t=>t.id===id)?.icon||1))+'<b>'+skillName249(id)+'</b><span>'+rank249(id)+' / 4</span></button>').join('');for(const b of list.querySelectorAll('[data-m249]'))b.onclick=()=>open249('mastery',Number(b.dataset.m249));const ad=actionDefs249.find(a=>a.id===k);info.innerHTML='<h2>'+skillName249(k)+'</h2><div class="ranks249">'+ranks249.map((v,i)=>'<span class="'+(rank>i?'earned249':'')+'">'+['I','II','III','IV'][i]+'</span>').join('')+'</div><progress max="120" value="'+xp+'"></progress><p>'+xp+' / 120 EXP</p><p>'+masteryText249(k)+'</p><p>'+T249('Rangos: 0 / 20 / 60 / 120 EXP. Progresa con impactos válidos y pruebas, no disparando al vacío.','Ranks: 0 / 20 / 60 / 120 XP. Progress through valid hits and trials, not firing into empty space.','Graus: 0 / 20 / 60 / 120 EXP. Progrida com acertos válidos e testes, não atirando no vazio.','Kademeler: 0 / 20 / 60 / 120 XP. Boşluğa atışla değil, geçerli isabet ve denemelerle ilerle.')+'</p>'+(ad?'<p>'+T249('Requisito de poder base','Base power requirement','Requisito de poder base','Temel güç şartı')+': '+powerText252(ad.level)+' PL · KI '+(ad.id==='solar'?30:ad.id==='sense'?10:ad.id==='after'?35:0)+'</p><button id="equip249" '+(saiState167().power<ad.level?'disabled':'')+'>'+word244(s.newEquipped.includes(k)?'unequip':'equip')+'</button>':'');const eq=info.querySelector('#equip249');if(eq)eq.onclick=()=>{const i=s.newEquipped.indexOf(k);if(i>=0)s.newEquipped.splice(i,1);else s.newEquipped.push(k);if(k==='guard')run249.guard=false;persistGame();open249('mastery',selected);};}
if(page==='companion'){title.textContent=w249('companion');list.innerHTML=['gohan','piccolo'].map((k,i)=>'<button data-co249="'+k+'" class="tech-row244"><b>'+(i?'Piccolo':'Gohan')+'</b><span>'+s.affinity[k]+' / 100</span></button>').join('');info.innerHTML='<h2>'+T249('Afinidad y ataques conjuntos','Affinity and joint attacks','Afinidade e ataques conjuntos','Yakınlık ve ortak saldırılar')+'</h2><p>'+T249('Gohan y Piccolo pueden acompañarte al explorar y en las pruebas de combate. Ayudan a atacar, pero debes dar el golpe final. Cada encargo juntos da +5 de afinidad. La afinidad mejora su apoyo. No sustituyen los aliados de las historias existentes.','Gohan and Piccolo can accompany exploration and combat trials. They help attack, but you must land the final hit. Each request together grants +5 affinity. Affinity improves support. They do not replace existing story allies.','Gohan e Piccolo acompanham exploração e testes de combate. Ajudam a atacar, mas você dá o golpe final. Cada pedido juntos dá +5 afinidade. Afinidade melhora o apoio. Não substituem aliados da história.','Gohan ve Piccolo keşifte ve dövüş denemelerinde eşlik eder. Saldırıya yardım ederler; son darbeyi sen vurursun. Birlikte her iş +5 yakınlık verir. Yakınlık desteği artırır. Hikâye yoldaşları değişmez.')+'</p><p>'+T249('Activo','Active','Ativo','Etkin')+': '+(s.companion||'—')+'</p><button id="dismiss249">'+T249('DESPEDIR','DISMISS','DISPENSAR','AYIR')+'</button>';for(const b of list.querySelectorAll('[data-co249]'))b.onclick=()=>{if(!raditzProgress168().defeated){toast(T249('Completa primero la historia de Raditz.','Complete Raditz’s story first.','Conclua a história de Raditz primeiro.','Önce Raditz hikâyesini tamamla.'));return;}s.companion=b.dataset.co249;run249.comp={x:player.x-90,y:player.y,cd:1,act:0};persistGame();open249('companion');};info.querySelector('#dismiss249').onclick=()=>{s.companion='';persistGame();open249('companion');};}return true;}
function masteryText249(k){const map={kame:['Cada rango reduce 5% el coste. Desde II puedes ajustar la dirección durante la carga con el control. III y IV amplían la duración visual del rayo; el impacto sigue siendo único.','Each rank reduces cost by 5%. From II, adjust direction during charging with the controls. III and IV extend beam visuals; damage remains a single hit.','Cada grau reduz 5% do custo. Desde II, ajuste a direção durante a carga. III e IV ampliam a duração visual; o dano continua único.','Her kademe bedeli %5 azaltır. II’den itibaren yüklerken yönü ayarla. III ve IV ışın görüntüsünü uzatır; hasar tek isabettir.'],kai:['Completa la persecución de Bubbles: 1 / 2 / 3 / 6 victorias habilitan ×2 / ×4 / ×10 / ×20. Conservas los multiplicadores anteriores. El desgaste aprobado continúa activo.','Complete Bubbles chases: 1 / 2 / 3 / 6 wins unlock ×2 / ×4 / ×10 / ×20. Previously unlocked multipliers remain. Approved strain remains active.','Complete a perseguição: 1 / 2 / 3 / 6 vitórias liberam ×2 / ×4 / ×10 / ×20. Multiplicadores anteriores ficam. O desgaste aprovado continua.','Bubbles kovalamacası: 1 / 2 / 3 / 6 zafer ×2 / ×4 / ×10 / ×20 açar. Önceki çarpanlar korunur. Onaylı yıpranma sürer.'],fly:['Cada rango adicional mejora la velocidad de vuelo un 5%. Progresa completando aros del circuito.','Each additional rank improves flight speed by 5%. Progress through circuit rings.','Cada grau extra melhora a velocidade de voo em 5%. Progrida pelos aros do circuito.','Her ek kademe uçuş hızını %5 artırır. Parkur halkalarıyla ilerle.'],guard:['Activa y desactiva el bloqueo. Reduce 70% del daño al gastar resistencia. No protege con resistencia agotada.','Toggle guard. Reduces damage by 70% by spending stamina. No protection with depleted stamina.','Ative e desative o bloqueio. Reduz 70% do dano gastando resistência. Não protege sem resistência.','Savunmayı aç/kapat. Dayanıklılık harcayarak hasarı %70 azaltır. Dayanıklılık bitince korumaz.'],dodge:['Cuesta 25 de resistencia. Evita impactos durante 0,32 s; los primeros 0,16 s dan una ventana de contraataque si esquivas un impacto real.','Costs 25 stamina. Avoids hits for 0.32 s; the first 0.16 s grant a counter window when a real impact is dodged.','Custa 25 resistência. Evita impactos por 0,32 s; os primeiros 0,16 s dão contra-ataque ao desviar de impacto real.','25 dayanıklılık harcar. 0,32 sn kaçınır; ilk 0,16 sn gerçek isabetten kaçınma karşı saldırı açar.'],sense:['Desde 10.000 PL base: muestra pulsos de ki de rivales, habitantes y pistas cercanas durante 8 s. Consume 10 ki.','From 10,000 base PL: displays ki pulses for rivals, residents and nearby clues for 8 s. Costs 10 ki.','Desde 10.000 PL base: mostra pulsos de rivais, moradores e pistas por 8 s. Custa 10 ki.','10.000 temel PL: rakip, sakin ve yakın ipuçlarının ki titreşimlerini 8 sn gösterir. 10 ki harcar.'],solar:['Desde 10.000 PL base: un destello retrasa la acción del rival cercano. Cada rango amplía el efecto 0,25 s. Consume 30 ki.','From 10,000 base PL: a flash delays a nearby rival’s action. Each rank extends the effect by 0.25 s. Costs 30 ki.','Desde 10.000 PL base: um clarão atrasa o rival próximo. Cada grau amplia o efeito em 0,25 s. Custa 30 ki.','10.000 temel PL: parlama yakın rakibi geciktirir. Her kademe etkiyi 0,25 sn uzatır. 30 ki harcar.'],after:['Desde 10.000 PL base: deja una imagen y se desplaza detrás del rival cercano si hay espacio. Cuesta 35 ki y 25 de resistencia. No es teletransporte libre.','From 10,000 base PL: leaves an image and moves behind a nearby rival if space permits. Costs 35 ki and 25 stamina. Not unrestricted teleportation.','Desde 10.000 PL base: deixa uma imagem e vai para trás do rival próximo se houver espaço. Custa 35 ki e 25 resistência. Não é teletransporte livre.','10.000 temel PL: bir görüntü bırakır, yer varsa yakın rakibin arkasına geçer. 35 ki ve 25 dayanıklılık harcar. Serbest ışınlanma değildir.']};return T249(...(map[k]||['Cada rango adicional aumenta 5% la eficacia de esta técnica. Encadena golpes para empujar al rival.','Each additional rank increases this technique’s effectiveness by 5%. Chain punches to push the rival.','Cada grau extra aumenta 5% a eficácia da técnica. Encadeie socos para empurrar o rival.','Her ek kademe bu tekniğin etkisini %5 artırır. Rakibi itmek için yumrukları zincirle.']));}
