// Save-safe Namek progression. Temporary bodies never overwrite the original Saiyan stats.
const ORDER264=['guldoBurter','recoomeJeice','ginyu','frog'];
const FIGHTERS264={guldo:{row:0,power:300000,hp:9000,color:'#a4dc74',speed:115},burter:{row:1,power:750000,hp:19000,color:'#55cfff',speed:285},recoome:{row:2,power:800000,hp:22000,color:'#ffbb64',speed:155},jeice:{row:3,power:700000,hp:18000,color:'#ff656b',speed:190},ginyu:{row:4,power:1400000,hp:32000,color:'#cc8aff',speed:200},stolen:{row:7,power:600000,hp:19000,color:'#ffad4c',speed:185}};
function normalize264(raw){
 const s=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
 const integer=(n,max=1e9)=>Number.isSafeInteger(n)?Math.max(0,Math.min(max,n)):0;
 s.v=1;s.serial=integer(s.serial);s.claimed=integer(s.claimed);s.wins=s.wins&&typeof s.wins==='object'&&!Array.isArray(s.wins)?s.wins:{};
 for(const id of ORDER264)s.wins[id]=integer(s.wins[id]);
 s.mode=['frog','vegeta'].includes(s.mode)?s.mode:'normal';s.recovery=Number.isFinite(s.recovery)?Math.max(0,Math.min(300,s.recovery)):0;
 s.trainingWins=integer(s.trainingWins);s.zenkai=s.zenkai&&typeof s.zenkai==='object'?s.zenkai:{};
 for(const k of ['remaining','cooldown'])s.zenkai[k]=Number.isFinite(s.zenkai[k])?Math.max(0,Math.min(k==='remaining'?10:90,s.zenkai[k])):0;
 s.zenkai.armed=s.zenkai.armed!==false;
 const a=s.active;if(a&&(!ORDER264.includes(a.id)||!Number.isSafeInteger(a.token)||a.token<=s.claimed||a.token>s.serial||!['intro','battle','phase','ending','intercept','failure'].includes(a.stage)))s.active=null;
 return s;
}
function canStart264(s,id,zarbon){if(!ORDER264.includes(id)||!zarbon||s.active||s.mode==='vegeta')return false;const i=ORDER264.indexOf(id);if(i&&!(s.wins[ORDER264[i-1]]>0))return false;if(s.mode==='frog'&&id!=='frog')return false;return id!=='frog'||s.mode==='frog'||s.wins.frog>0;}
function receipt264(s){const a=s.active;if(!a||a.token<=s.claimed||a.stage!=='ending'||!a.dealt)return false;s.claimed=a.token;s.wins[a.id]++;s.active=null;return a.id;}
function zenkaiStep264(z,{dt,hp,max,hurt,alive,eligible}){
 if(!eligible||!alive){z.remaining=0;return 0;}z.cooldown=Math.max(0,(z.cooldown||0)-dt);
 if(hp/max>.35&&!z.remaining&&!z.cooldown)z.armed=true;
 if(!z.remaining&&z.armed&&!z.cooldown&&hurt&&hp>0&&hp/max<=.15){z.remaining=10;z.armed=false;return 0;}
 if(z.remaining>0){z.remaining=Math.max(0,z.remaining-dt);if(z.remaining===0){z.cooldown=90;return 1;}}
 return 0;
}

